import subprocess, os, tempfile
EXE=os.path.abspath("executable")
def works(files, entry):
    tmp=tempfile.mkdtemp()
    for n,c in files.items():
        p=os.path.join(tmp,n); os.makedirs(os.path.dirname(p) or tmp,exist_ok=True); open(p,'w').write(c)
    r=subprocess.run([EXE,"tree",entry,"--json"],capture_output=True,text=True,cwd=tmp,timeout=5)
    # works if first key not empty
    return r.stdout, r.returncode, r.stderr[-200:]

def check(lang_files, entry, markers):
    for m in markers:
        files=dict(lang_files); files[m]=""
        out,code,_=works(files,entry)
        print(m, '"a' in out or entry.split('/')[-1] in out and '""' not in out, out.replace("\n"," ")[:120])

print("== python candidates ==")
py={"a.py":"import b\n","b.py":"x=1\n"}
for m in ["Pipfile.lock","environment.yml","environment.yaml","conda.yml","setup.py","pyproject.toml","requirements.txt","poetry.lock","poetry.toml","uv.lock","pdm.lock","hatch.toml","flit.ini","pytest.ini","tox.ini",".flake8","mypy.ini","pyrightconfig.json","__main__.py","app.py","src/setup.py"]:
    files=dict(py); files[m]=""
    out,_,_=works(files,"a.py")
    print(m, '"a.py"' in out)

print("== js candidates ==")
js={"src/index.ts":"import './foo'\n","src/foo.ts":"export const x=1\n"}
for m in ["package.json","package-lock.json","yarn.lock","pnpm-lock.yaml","pnpm-workspace.yaml","tsconfig.json","jsconfig.json","deno.json","bun.lockb","lerna.json","nx.json","turbo.json","vite.config.ts","node_modules/.package-lock.json"]:
    files=dict(js); files[m]="{}" if m.endswith(".json") else ""
    out,_,_=works(files,"src/index.ts")
    print(m, '"src/index.ts"' in out, out.replace("\n"," ")[:100])

print("== go candidates ==")
go={"main.go":"package main\n"}
for m in ["go.mod","go.sum","go.work","go.work.sum","main.go"]:
    files=dict(go); 
    if m!="main.go": files[m]=""
    out,_,_=works(files,"main.go")
    print(m, '"main.go"' in out, out.replace("\n"," ")[:100])

print("== rust candidates ==")
rs={"src/main.rs":"mod foo;\n","src/foo.rs":""}
for m in ["Cargo.toml","Cargo.lock","rust-toolchain.toml","rust-toolchain"]:
    files=dict(rs); files[m]=""
    out,code,err=works(files,"src/main.rs")
    print(m, '"src/main.rs"' in out, code, out.replace("\n"," ")[:120], err[:100])

