{"command":"python3 - << 'PY'
import sys; sys.path.insert(0,'/tmp'); from probe import *
import itertools
def tree(files, entry="src/index.ts", extra=[]):
    tmp=mk({"package.json":'{"name":"x"}', **files})
    r=subprocess.run([EXE,"tree",entry,"--json"]+extra,capture_output=True,text=True,cwd=tmp)
    # parse stdout json tree first child key
    try:
        import json; j=json.loads(r.stdout); t=j["tree"]; 
        def first(d):
            return list(d.keys())
        res=t
    except: res=r.stdout
    print(files, "=>", r.stdout.replace("\n"," "))
exts=["js","ts","tsx","jsx","mjs","cjs","d.ts"]
# pairwise priority for file foo.<ext>
for a,b in itertools.combinations(exts,2):
    tmp=mk({"package.json":'{"name":"x"}',"src/index.ts":"import './foo'\n", f"src/foo.{a}":"", f"src/foo.{b}":""})
    r=subprocess.run([EXE,"tree","src/index.ts","--json"],capture_output=True,text=True,cwd=tmp)
    import json; j=json.loads(r.stdout); child=list(list(j["tree"].values())[0].keys())[0] if list(j["tree"].values())[0] else None
    print(a,b,"wins",child)
PY
