package check

import (
	"gopkg.in/yaml.v3"
)

// WhiteListEntries represents an allow rule: either a plain list of
// patterns or an object with a "to" list and a "reason".
type WhiteListEntries struct {
	To     []string
	Reason string
}

func (w *WhiteListEntries) UnmarshalYAML(value *yaml.Node) error {
	if value.Kind == yaml.SequenceNode {
		var list []string
		if err := value.Decode(&list); err != nil {
			return err
		}
		w.To = list
		return nil
	}
	var obj struct {
		To     []string `yaml:"to"`
		Reason string   `yaml:"reason"`
	}
	if err := value.Decode(&obj); err != nil {
		return err
	}
	w.To = obj.To
	w.Reason = obj.Reason
	return nil
}

// BlackListEntry represents a single deny rule: either a plain pattern
// string or an object with "to" and "reason".
type BlackListEntry struct {
	To     string
	Reason string
}

func (b *BlackListEntry) UnmarshalYAML(value *yaml.Node) error {
	if value.Kind == yaml.MappingNode {
		var obj struct {
			To     string `yaml:"to"`
			Reason string `yaml:"reason"`
		}
		if err := value.Decode(&obj); err != nil {
			return err
		}
		b.To = obj.To
		b.Reason = obj.Reason
		return nil
	}
	var s string
	if err := value.Decode(&s); err != nil {
		return err
	}
	b.To = s
	return nil
}

// Config holds dependency check settings.
type Config struct {
	Entrypoints               []string                      `yaml:"entrypoints"`
	AllowCircularDependencies bool                          `yaml:"allowCircularDependencies"`
	Allow                     map[string]WhiteListEntries   `yaml:"allow"`
	Deny                      map[string][]BlackListEntry   `yaml:"deny"`
	Aliases                   map[string][]string           `yaml:"aliases"`
}
EOF
cat > internal/config/config.go <<'EOF'
package config

import (
	"bytes"
	"fmt"
	"os"
	"path/filepath"

	"gopkg.in/yaml.v3"

	"deptree/internal/check"
	"deptree/internal/js"
	"deptree/internal/python"
	"deptree/internal/rust"
)

// Config is the root of the .dep-tree.yml configuration file.
type Config struct {
	Exclude       []string     `yaml:"exclude"`
	Only          []string     `yaml:"only"`
	UnwrapExports bool         `yaml:"unwrapExports"`
	Check         check.Config `yaml:"check"`
	Js            js.Config    `yaml:"js"`
	Python        python.Config `yaml:"python"`
	Rust          rust.Config  `yaml:"rust"`
}

// Default returns a configuration populated with default values.
func Default() Config {
	return Config{
		Js: js.Config{
			Workspaces:    true,
			TsConfigPaths: true,
		},
	}
}

// Loaded describes a configuration file that was (or was not) loaded.
type Loaded struct {
	Config Config
	Path   string // path as provided on the command line
	Exists bool
}

// Dir returns the directory portion of the config path as provided.
func (l *Loaded) Dir() string {
	return filepath.Dir(l.Path)
}

// AbsDir returns the absolute directory containing the config file.
func (l *Loaded) AbsDir() string {
	abs, err := filepath.Abs(l.Dir())
	if err != nil {
		return l.Dir()
	}
	return abs
}

// Load reads the configuration file at path. If changed is false and the
// file does not exist, a default configuration is returned without error.
func Load(path string, changed bool) (*Loaded, error) {
	loaded := &Loaded{Config: Default(), Path: path}
	data, err := os.ReadFile(path)
	if err != nil {
		if !changed && os.IsNotExist(err) {
			return loaded, nil
		}
		return nil, err
	}
	loaded.Exists = true
	dec := yaml.NewDecoder(bytes.NewReader(data))
	dec.KnownFields(true)
	cfg := Default()
	if err := dec.Decode(&cfg); err != nil {
		return nil, fmt.Errorf("config file %q is not a valid yml file: %w", path, err)
	}
	loaded.Config = cfg
	return loaded, nil
}
EOF
