cat > internal/langcore/langcore.go <<'EOF'
package langcore

import (
	"bytes"
	"encoding/json"
	"hash/fnv"
	"os"
	"path/filepath"
	"strings"
)

// Info describes a single parsed source file.
type Info struct {
	Abs     string
	Display string
	Group   string
	Package string
	Loc     int
}

// Result is the outcome of parsing one file.
type Result struct {
	Info   Info
	Deps   []string
	Errors []string
}

// Parser parses files of a single language.
type Parser interface {
	Parse(abs string) (*Result, error)
}

// Loc counts lines of code the same way the entropy view does: by the
// number of newline bytes present in the contents.
func Loc(contents []byte) int {
	return bytes.Count(contents, []byte("\n"))
}

// ID returns the FNV-1a 32-bit hash of a path, used as a node id.
func ID(abs string) uint32 {
	h := fnv.New32a()
	_, _ = h.Write([]byte(abs))
	return h.Sum32()
}

// IsFile reports whether path exists and is a regular file.
func IsFile(path string) bool {
	info, err := os.Stat(path)
	return err == nil && info.Mode().IsRegular()
}

// IsDir reports whether path exists and is a directory.
func IsDir(path string) bool {
	info, err := os.Stat(path)
	return err == nil && info.IsDir()
}

// FindMarkerRoot walks up from startDir looking for a directory that
// contains any of the marker files. It returns "" when none is found.
func FindMarkerRoot(startDir string, markers []string) string {
	dir := startDir
	for {
		for _, m := range markers {
			if _, err := os.Stat(filepath.Join(dir, m)); err == nil {
				return dir
			}
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			return ""
		}
		dir = parent
	}
}

// PackageJSON is a minimal view of a package.json file.
type PackageJSON struct {
	Name       string          `json:"name"`
	Main       json.RawMessage `json:"main"`
	Workspaces json.RawMessage `json:"workspaces"`
