package graph

import (
	"path/filepath"
	"sort"
	"strings"

	"deptree/internal/langcore"
)

// Node is one file in the dependency graph.
type Node struct {
	Info   langcore.Info
	Deps   []string // absolute paths, in discovery order
	Errors []string
}

// Graph is a loaded dependency graph.
type Graph struct {
	Nodes []*Node
	byAbs map[string]*Node
	Roots []string
	// Errors maps a node's display path to its parse errors.
	Errors map[string][]string
}

// Progress receives loading progress updates.
type Progress interface {
	Add(current int, total int)
	Finish(total int)
}

type noopProgress struct{}

func (noopProgress) Add(int, int) {}
func (noopProgress) Finish(int)   {}

// Options controls graph loading.
type Options struct {
	Fixed   bool
	Allowed map[string]bool
}

// Load parses the initial files and, unless Fixed is set, recursively
// everything they depend on, in breadth-first order.
func Load(initial []string, parser langcore.Parser, ignore func(string) bool, progress Progress, opts Options) (*Graph, error) {
	if progress == nil {
		progress = noopProgress{}
	}
	if ignore == nil {
		ignore = func(string) bool { return false }
	}
	g := &Graph{byAbs: map[string]*Node{}, Errors: map[string][]string{}}
	// Queue of absolute paths, preserving the order provided.
	queue := []string{}
	enqueued := map[string]bool{}
	for _, f := range initial {
		abs := filepath.Clean(f)
		if enqueued[abs] {
			continue
		}
		enqueued[abs] = true
		queue = append(queue, abs)
		g.Roots = append(g.Roots, abs)
	}
	total := len(queue)
	loaded := 0
	for i := 0; i < len(queue); i++ {
		abs := queue[i]
		if ignore(abs) {
			continue
		}
		if opts.Fixed && opts.Allowed != nil && !opts.Allowed[abs] {
			continue
		}
		result, err := parser.Parse(abs)
		if err != nil {
			return nil, err
		}
		node := &Node{Info: result.Info, Errors: result.Errors}
		if len(result.Errors) > 0 {
			g.Errors[result.Info.Display] = append([]string{}, result.Errors...)
		}
		seenDep := map[string]bool{}
		for _, dep := range result.Deps {
			dep = filepath.Clean(dep)
			if dep == abs || seenDep[dep] {
				continue
			}
			seenDep[dep] = true
			if opts.Fixed && opts.Allowed != nil && !opts.Allowed[dep] {
				continue
			}
			node.Deps = append(node.Deps, dep)
			if !enqueued[dep] {
				enqueued[dep] = true
				queue = append(queue, dep)
				total++
			}
		}
		g.Nodes = append(g.Nodes, node)
		g.byAbs[abs] = node
		loaded++
		progress.Add(loaded, total)
	}
	// Drop edges pointing at files that were not loaded (ignored files).
	for _, n := range g.Nodes {
		kept := n.Deps[:0]
		seen := map[string]bool{}
		for _, d := range n.Deps {
			if g.byAbs[d] != nil && !seen[d] {
				seen[d] = true
				kept = append(kept, d)
			}
		}
		n.Deps = kept
	}
	progress.Finish(total)
	return g, nil
}

// Node returns the node for an absolute path, if loaded.
func (g *Graph) Node(abs string) *Node {
	return g.byAbs[filepath.Clean(abs)]
}

// Children returns the loaded child nodes of a node.
func (g *Graph) Children(n *Node) []*Node {
	out := []*Node{}
	for _, d := range n.Deps {
		if c := g.byAbs[d]; c != nil {
			out = append(out, c)
		}
	}
	return out
}

// Tree builds the nested tree representation used by the tree command
// and collects the circular dependencies encountered along the way.
func (g *Graph) Tree(entryAbs string) (map[string]interface{}, [][]string) {
	entry := g.Node(entryAbs)
	if entry == nil {
		return nil, [][]string{}
	}
	cycles := [][]string{}
	seenCycle := map[string]bool{}
	var build func(n *Node, stack []*Node) map[string]interface{}
	build = func(n *Node, stack []*Node) map[string]interface{} {
		var out map[string]interface{}
		for _, child := range g.Children(n) {
			idx := -1
			for i, s := range stack {
				if s == child {
					idx = i
					break
				}
			}
			if idx >= 0 {
				cycle := []string{}
				for _, s := range stack[idx:] {
					cycle = append(cycle, s.Info.Display)
				}
				cycle = append(cycle, child.Info.Display)
				key := strings.Join(cycle, "\x00")
				if !seenCycle[key] {
					seenCycle[key] = true
					cycles = append(cycles, cycle)
				}
				continue
			}
			if out == nil {
				out = map[string]interface{}{}
			}
			out[child.Info.Display] = build(child, append(stack, child))
		}
		return out
	}
	tree := build(entry, []*Node{entry})
	if tree == nil {
		tree = map[string]interface{}{}
	}
	// The root level maps the entrypoint itself.
	root := map[string]interface{}{entry.Info.Display: nil}
	if len(tree) > 0 {
		root[entry.Info.Display] = tree
	}
	return root, cycles
}

// CircularDependencies returns cycles found by a depth-first walk of
// the graph starting at its roots.
func (g *Graph) CircularDependencies() [][]string {
	cycles := [][]string{}
	seenCycle := map[string]bool{}
	state := map[string]int{} // 0 unvisited, 1 in stack, 2 done
	var stack []*Node
	var visit func(n *Node)
	visit = func(n *Node) {
		state[n.Info.Abs] = 1
		stack = append(stack, n)
		for _, child := range g.Children(n) {
			switch state[child.Info.Abs] {
			case 1:
				idx := 0
				for i, s := range stack {
					if s == child {
						idx = i
						break
					}
				}
				cycle := []string{}
				for _, s := range stack[idx:] {
					cycle = append(cycle, s.Info.Display)
				}
				cycle = append(cycle, child.Info.Display)
				key := strings.Join(cycle, "\x00")
				if !seenCycle[key] {
					seenCycle[key] = true
					cycles = append(cycles, cycle)
				}
			case 0:
				visit(child)
			}
		}
		stack = stack[:len(stack)-1]
		state[n.Info.Abs] = 2
	}
	for _, rootAbs := range g.Roots {
		if n := g.Node(rootAbs); n != nil && state[n.Info.Abs] == 0 {
			visit(n)
		}
	}
	return cycles
}

// SortedNodes returns nodes sorted by display path.
func (g *Graph) SortedNodes() []*Node {
	out := append([]*Node{}, g.Nodes...)
	sort.Slice(out, func(i, j int) bool { return out[i].Info.Display < out[j].Info.Display })
	return out
}
