package python

import (
	"os"
	"path/filepath"
	"strings"

	"deptree/internal/langcore"
)

var rootMarkers = []string{"setup.py", "pyproject.toml", "requirements.txt", "poetry.lock", "poetry.toml"}

// Parser parses Python files.
type Parser struct {
	excludeConditional bool
	rootCache          map[string]string
}

// NewParser creates a Python parser.
func NewParser(excludeConditional bool) *Parser {
	return &Parser{excludeConditional: excludeConditional, rootCache: map[string]string{}}
}

func (p *Parser) rootFor(abs string) string {
	dir := filepath.Dir(abs)
	if r, ok := p.rootCache[dir]; ok {
		return r
	}
	r := langcore.FindMarkerRoot(dir, rootMarkers)
	p.rootCache[dir] = r
	return r
}

func (p *Parser) display(abs string) string {
	return langcore.RelativeDisplay(p.rootFor(abs), abs)
}

// Parse reads a Python file and resolves its imports to local files.
func (p *Parser) Parse(abs string) (*langcore.Result, error) {
	contents, err := os.ReadFile(abs)
	if err != nil {
		return nil, err
	}
	imports := scanImports(string(contents))
	res := &langcore.Result{Info: langcore.Info{
		Abs:     abs,
		Display: p.display(abs),
		Loc:     langcore.Loc(contents),
	}}
	seen := map[string]bool{}
	add := func(dep string) {
		if dep == "" || dep == abs || seen[dep] {
			return
		}
		seen[dep] = true
		res.Deps = append(res.Deps, dep)
	}
	for _, imp := range imports {
		if p.excludeConditional && imp.conditional {
			continue
		}
		if imp.from {
			deps, errStr := p.resolveFrom(abs, imp)
			for _, d := range deps {
				add(d)
			}
			if errStr != "" {
				res.Errors = append(res.Errors, errStr)
			}
		} else {
			add(p.resolvePlain(abs, imp.module))
		}
	}
	return res, nil
}

// searchBases returns the directories to resolve absolute imports from,
// most specific first.
func (p *Parser) searchBases(abs string) []string {
	bases := []string{filepath.Dir(abs)}
	if root := p.rootFor(abs); root != "" && root != bases[0] {
		bases = append(bases, root)
	} else if root == "" {
		if cwd, err := os.Getwd(); err == nil && cwd != bases[0] {
			bases = append(bases, cwd)
		}
	}
	return bases
}

func (p *Parser) resolvePlain(abs, dotted string) string {
	if dotted == "" {
		return ""
	}
	parts := strings.Split(dotted, ".")
	for _, base := range p.searchBases(abs) {
		candidate := filepath.Join(append([]string{base}, parts...)...)
		if langcore.IsFile(candidate + ".py") {
			return candidate + ".py"
		}
		if langcore.IsFile(filepath.Join(candidate, "__init__.py")) {
			return filepath.Join(candidate, "__init__.py")
		}
	}
	return ""
}

func (p *Parser) resolveFrom(abs string, imp pyImport) ([]string, string) {
	var modulePath string
	found := false
	if imp.level > 0 {
		dir := filepath.Dir(abs)
		for i := 1; i < imp.level; i++ {
			dir = filepath.Dir(dir)
		}
		if imp.module == "" {
			modulePath = dir
		} else {
			modulePath = filepath.Join(append([]string{dir}, strings.Split(imp.module, ".")...)...)
		}
		found = true
	} else {
		if imp.module == "" {
			return nil, ""
		}
		parts := strings.Split(imp.module, ".")
		for _, base := range p.searchBases(abs) {
			candidate := filepath.Join(append([]string{base}, parts...)...)
			if langcore.IsFile(candidate+".py") || langcore.IsDir(candidate) {
				modulePath = candidate
				found = true
				break
			}
		}
	}
	if !found {
		return nil, ""
	}
	if langcore.IsFile(modulePath + ".py") {
		return []string{modulePath + ".py"}, ""
	}
	if !langcore.IsDir(modulePath) {
		return nil, ""
	}
	// Module is a directory: imported names are looked up as plain
	// "<name>.py" files inside it, falling back to its __init__.py.
	deps := []string{}
	hasStar := false
	firstMissing := ""
	for _, name := range imp.names {
		if name == "*" {
			hasStar = true
			if langcore.IsFile(filepath.Join(modulePath, "__init__.py")) {
				deps = appendUnique(deps, filepath.Join(modulePath, "__init__.py"))
			}
			continue
		}
		candidate := filepath.Join(modulePath, name+".py")
		if langcore.IsFile(candidate) {
			deps = appendUnique(deps, candidate)
		} else if langcore.IsFile(filepath.Join(modulePath, "__init__.py")) {
			deps = appendUnique(deps, filepath.Join(modulePath, "__init__.py"))
		} else if firstMissing == "" {
			firstMissing = name
		}
	}
	if len(deps) == 0 && firstMissing != "" && !hasStar {
		return nil, "cannot import file " + firstMissing + ".py from directory " + modulePath
	}
	if len(deps) == 0 && firstMissing != "" && len(imp.names) > 0 && !onlyStar(imp.names) && hasStar {
		// A "*" alongside failing names behaves like the plain names.
		return nil, "cannot import file " + firstMissing + ".py from directory " + modulePath
	}
	return deps, ""
}

func onlyStar(names []string) bool {
	for _, n := range names {
		if n != "*" {
			return false
		}
	}
	return true
}

func appendUnique(list []string, v string) []string {
	for _, e := range list {
		if e == v {
			return list
		}
	}
	return append(list, v)
}
