			// line continuation: does not end the logical line
			i += 2
			line++
		case c == '"' || c == '\'':
			i = skipString(src, i, &line)
			push("STRING", 's')
		case isIdentStart(c):
			j := i + 1
			for j < n && isIdentPart(src[j]) {
				j++
			}
			word := src[i:j]
			// String literal with a prefix, e.g. r"..." or f'...':
			if j < n && (src[j] == '"' || src[j] == '\'') && isStringPrefix(word) {
				i = skipString(src, j, &line)
				push("STRING", 's')
			} else {
				push(word, 'i')
				i = j
			}
		case c >= '0' && c <= '9':
			j := i + 1
			for j < n && (isIdentPart(src[j]) || src[j] == '.') {
				j++
			}
			push(src[i:j], 's')
			i = j
		default:
			push(string(c), 'p')
			i++
		}
	}
	return toks
}

func isStringPrefix(w string) bool {
	if len(w) == 0 || len(w) > 3 {
		return false
	}
	for _, r := range w {
		switch r {
		case 'r', 'R', 'b', 'B', 'f', 'F', 'u', 'U':
		default:
			return false
		}
	}
	return true
}

func skipString(src string, start int, line *int) int {
	quote := src[start]
	i := start + 1
	n := len(src)
	triple := i+1 < n && src[i] == quote && src[i+1] == quote
	if triple {
		i += 2
		for i < n {
			if src[i] == '\n' {
				*line++
			}
			if src[i] == quote && i+2 < n && src[i+1] == quote && src[i+2] == quote {
				// Ensure this is not escaped in a non-raw string; a
				// preceding backslash escapes it.
				if i > 0 && src[i-1] == '\\' {
					i++
					continue
				}
				return i + 3
			}
			i++
		}
		return n
	}
	for i < n {
		if src[i] == '\\' {
			i += 2
			continue
		}
		if src[i] == quote {
			return i + 1
		}
		if src[i] == '\n' {
			// Unterminated string; bail out at the line end.
			return i
		}
		i++
	}
	return n
}

func isIdentStart(c byte) bool {
	return c == '_' || (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c >= 0x80
}

func isIdentPart(c byte) bool {
	return isIdentStart(c) || (c >= '0' && c <= '9')
}

// scanImports extracts import statements from Python source. Imports
// that are not at module top level are marked conditional.
func scanImports(src string) []pyImport {
	toks := tokenize(src)
	var imports []pyImport
	// Split into logical lines: newlines inside brackets do not split.
	type stmt struct {
		toks        []token
		indent      int
		afterColon  bool
	}
	lines := splitLogicalLines(src, toks)
	for _, ln := range lines {
		conditional := ln.indent > 0
		// Find import statements within the logical line. Simple
		// statements may be separated by ";" or follow a ":".
		segments := splitStatements(ln.toks)
		for _, seg := range segments {
			if len(seg.toks) == 0 {
				continue
			}
			cond := conditional || seg.afterColon
			if imp, ok := parseImport(seg.toks, cond); ok {
				imports = append(imports, imp)
			}
		}
	}
	return imports
}

type lineInfo struct {
	toks   []token
	indent int
}

type segment struct {
	toks       []token
	afterColon bool
}

func splitLogicalLines(src string, toks []token) []lineInfo {
	// Compute the indentation (in visual columns, tab = 8) of each
	// physical line.
	indents := map[int]int{}
	col := 0
	line := 1
	for _, r := range src {
		if r == '\n' {
			line++
			col = 0
			continue
		}
		if _, ok := indents[line]; !ok {
			indents[line] = col
		}
		if r == '\t' {
			col += 8 - (col % 8)
		} else if r != ' ' && r != '\r' {
			if _, ok := indents[line]; ok {
				// already recorded first non-space column
			}
			col++
		} else {
			col++
		}
	}
	// Recompute simply: indentation is the column of the first
	// non-whitespace character.
	indents = map[int]int{}
	for idx, text := range strings.Split(src, "\n") {
		col = 0
		for _, r := range text {
			if r == ' ' {
				col++
			} else if r == '\t' {
				col += 8 - (col % 8)
			} else {
				break
			}
		}
		indents[idx+1] = col
	}
	var lines []lineInfo
	depth := 0
	var current []token
	currentIndent := 0
	flush := func() {
		if len(current) > 0 {
			lines = append(lines, lineInfo{current, currentIndent})
			current = nil
		}
	}
	for _, t := range toks {
		if t.kind == 'p' {
			switch t.text {
			case "(", "[", "{":
				depth++
			case ")", "]", "}":
				depth--
			}
		}
		if t.kind == 'n' && depth <= 0 {
			flush()
			continue
		}
		if t.kind == 'n' {
			continue
		}
		if len(current) == 0 {
			currentIndent = indents[t.line]
		}
		current = append(current, t)
	}
	flush()
	return lines
}

// splitStatements splits a logical line into simple statements at
// semicolons, and flags statements that follow a top-level colon as
// belonging to a compound statement's inline suite.
func splitStatements(toks []token) []segment {
	var segs []segment
	var current []token
	afterColon := false
	depth := 0
	emit := func() {
		if len(current) > 0 {
			segs = append(segs, segment{current, afterColon})
			current = nil
		}
	}
	for _, t := range toks {
		if t.kind == 'p' {
			switch t.text {
			case "(", "[", "{":
				depth++
			case ")", "]", "}":
				depth--
			case ";":
				if depth == 0 {
					emit()
					continue
				}
			case ":":
				if depth == 0 {
					// A colon ends a compound header (if/for/def/...);
					// whatever follows is its inline suite. Colons in
					// other contexts (slices, annotations) are rare on
					// the same statement as an import.
					current = append(current, t)
					emit()
					afterColon = true
					continue
				}
			}
		}
		current = append(current, t)
	}
	emit()
	return segs
}

// parseImport parses one simple statement, if it is an import.
func parseImport(toks []token, conditional bool) (pyImport, bool) {
	if len(toks) == 0 || toks[0].kind != 'i' {
		return pyImport{}, false
	}
	switch toks[0].text {
	case "import":
		// Only the first dotted name is taken.
		name, _ := parseDotted(toks, 1)
		if name == "" {
			return pyImport{}, false
		}
		return pyImport{module: name, conditional: conditional}, true
	case "from":
		i := 1
		level := 0
		for i < len(toks) && toks[i].text == "." {
			level++
			i++
		}
		module := ""
		if i < len(toks) && toks[i].kind == 'i' && toks[i].text != "import" {
			var consumed int
			module, consumed = parseDotted(toks, i)
			i += consumed
		}
		if i >= len(toks) || toks[i].text != "import" {
			return pyImport{}, false
		}
		i++
		names := parseImportNames(toks[i:])
		return pyImport{from: true, level: level, module: module, names: names, conditional: conditional}, true
	}
	return pyImport{}, false
}

// parseDotted parses a dotted name starting at index i.
func parseDotted(toks []token, i int) (string, int) {
	if i >= len(toks) || toks[i].kind != 'i' {
		return "", 0
	}
	parts := []string{toks[i].text}
	j := i + 1
	for j+1 < len(toks) && toks[j].text == "." && toks[j+1].kind == 'i' {
		parts = append(parts, toks[j+1].text)
		j += 2
	}
	return strings.Join(parts, "."), j - i
}

// parseImportNames parses the name list of a from-import.
func parseImportNames(toks []token) []string {
	names := []string{}
	i := 0
	expectName := true
	for i < len(toks) {
		t := toks[i]
		if t.text == "(" || t.text == ")" || t.text == "," {
			if t.text == "," {
				expectName = true
			}
			i++
			continue
		}
		if expectName {
			if t.text == "*" {
				names = append(names, "*")
				expectName = false
				i++
				continue
			}
			if t.kind == 'i' {
				names = append(names, t.text)
				expectName = false
				i++
				// Skip "as alias".
				if i+1 < len(toks) && toks[i].text == "as" {
					i += 2
				}
				continue
			}
		}
		i++
	}
	return names
}
