// Package dstar implements doublestar-style glob matching.
package dstar

import (
	"path/filepath"
	"strings"
)

// Validate reports whether the pattern is syntactically valid.
func Validate(pattern string) bool {
	for _, seg := range strings.Split(pattern, "/") {
		if seg == "**" {
			continue
		}
		if _, err := filepath.Match(seg, ""); err != nil {
			return false
		}
	}
	return true
}

// Match reports whether name matches the doublestar pattern. Both are
// slash-separated paths.
func Match(pattern, name string) bool {
	if !Validate(pattern) {
		return false
	}
	patSegs := strings.Split(pattern, "/")
	nameSegs := strings.Split(name, "/")
	return matchSegments(patSegs, nameSegs)
}

func matchSegments(pat, name []string) bool {
	for len(pat) > 0 {
		if pat[0] == "**" {
			// "**" matches zero or more whole segments.
			for skip := 0; skip <= len(name); skip++ {
				if matchSegments(pat[1:], name[skip:]) {
					return true
				}
			}
			return false
		}
		if len(name) == 0 {
			return false
		}
		ok, err := filepath.Match(pat[0], name[0])
		if err != nil || !ok {
			return false
		}
		pat = pat[1:]
		name = name[1:]
	}
	return len(name) == 0
}

// HasMagic reports whether the pattern contains glob metacharacters.
func HasMagic(pattern string) bool {
	return strings.ContainsAny(pattern, "*?[\\")
}
