{"command":"cat > internal/js/lex.go <<'EOF'
package js

import (
	"strconv"
	"strings"
	"unicode"
	"unicode/utf8"
)

type tokKind int

const (
	tIdent tokKind = iota
	tString
	tTemplate
	tNumber
	tPunct
)

type token struct {
	kind tokKind
	val  string
}

func isIdentStart(r rune) bool {
	return r == '_' || r == '$' || unicode.IsLetter(r)
}

func isIdentPart(r rune) bool {
	return r == '_' || r == '$' || unicode.IsLetter(r) || unicode.IsDigit(r)
}

// tokenizeJS splits JS/TS source into tokens, discarding comments and
// the contents of string and template literals (string tokens retain
// their decoded value).
func tokenizeJS(src string) []token {
	var toks []token
	runes := []rune(src)
	i := 0
	n := len(runes)
	prev := token{kind: tPunct, val: ""}
	emit := func(t token) {
		toks = append(toks, t)
		prev = t
	}
	for i < n {
		r := runes[i]
		switch {
		case r == ' ' || r == '\t' || r == '\n' || r == '\r':
			i++
		case r == '/' && i+1 < n && runes[i+1] == '/':
			for i < n && runes[i] != '\n' {
				i++
			}
		case r == '/' && i+1 < n && runes[i+1] == '*':
			i += 2
			for i+1 < n && !(runes[i] == '*' && runes[i+1] == '/') {
				i++
			}
			i += 2
			if i > n {
				i = n
			}
		case r == '/' && regexAllowed(prev):
			// Regex literal.
			i++
			inClass := false
			for i < n {
				if runes[i] == '\\' {
					i += 2
					continue
				}
				if runes[i] == '[' {
					inClass = true
				} else if runes[i] == ']' {
					inClass = false
				} else if runes[i] == '/' && !inClass {
					i++
					break
				} else if runes[i] == '\n' {
					break
				}
				i++
			}
			for i < n && isIdentPart(runes[i]) {
				i++
			}
			emit(token{tString, ""})
		case r == '"' || r == '\'':
			j := i + 1
			var sb strings.Builder
			for j < n {
				if runes[j] == '\\' && j+1 < n {
					sb.WriteString(decodeEscape(runes, &j))
					continue
				}
				if runes[j] == r || runes[j] == '\n' {
					break
				}
				sb.WriteRune(runes[j])
				j++
			}
			if j < n && runes[j] == r {
				j++
			}
			emit(token{tString, sb.String()})
			i = j
		case r == '`':
			i = skipTemplate(runes, i)
			emit(token{tTemplate, ""})
		case isIdentStart(r):
			j := i + 1
			for j < n && isIdentPart(runes[j]) {
				j++
			}
			emit(token{tIdent, string(runes[i:j])})
			i = j
		case unicode.IsDigit(r):
			j := i + 1
			for j < n && (isIdentPart(runes[j]) || runes[j] == '.') {
				j++
			}
			emit(token{tNumber, string(runes[i:j])})
			i = j
		default:
			// Group a few multi-character operators that matter.
			if i+2 < n && string(runes[i:i+3]) == "..." {
				emit(token{tPunct, "..."})
				i += 3
			} else {
				emit(token{tPunct, string(r)})
				i++
			}
		}
	}
	return toks
}

func regexAllowed(prev token) bool {
	if prev.val == "" {
		return true
	}
	if prev.kind == tIdent {
		switch prev.val {
		case "return", "typeof", "case", "in", "of", "new", "delete", "void", "instanceof", "yield", "await", "else", "do":
			return true
		}
		return false
	}
	if prev.kind == tString || prev.kind == tNumber || prev.kind == tTemplate {
		return false
	}
	switch prev.val {
	case ")", "]", "}":
		return false
	}
	return true
}

func decodeEscape(runes []rune, j *int) string {
	// runes[*j] is the backslash.
	if *j+1 >= len(runes) {
		*j++
		return "\\"
	}
	c := runes[*j+1]
	switch c {
	case 'n':
		*j += 2
		return "\n"
	case 't':
		*j += 2
		return "\t"
	case 'r':
		*j += 2
		return "\r"
	case 'b':
		*j += 2
		return "\b"
	case 'f':
		*j += 2
		return "\f"
	case 'v':
		*j += 2
		return "\v"
	case '0':
		*j += 2
		return "\x00"
	case 'x':
		if *j+3 < len(runes) {
			if v, err := strconv.ParseInt(string(runes[*j+2:*j+4]), 16, 32); err == nil {
				*j += 4
				return string(rune(v))
			}
		}
		*j += 2
		return "x"
	case 'u':
		if *j+2 < len(runes) && runes[*j+2] == '{' {
			k := *j + 3
			for k < len(runes) && runes[k] != '}' {
				k++
			}
			if k < len(runes) {
				if v, err := strconv.ParseInt(string(runes[*j+3:k]), 16, 32); err == nil {
					*j = k + 1
					return string(rune(v))
				}
			}
			*j += 2
			return "u"
		}
		if *j+5 < len(runes) {
			if v, err := strconv.ParseInt(string(runes[*j+2:*j+6]), 16, 32); err == nil {
				*j += 6
				return string(rune(v))
			}
		}
		*j += 2
		return "u"
	default:
		*j += 2
		return string(c)
	}
}

func skipTemplate(runes []rune, start int) int {
	i := start + 1
	n := len(runes)
	for i < n {
		switch runes[i] {
		case '\\':
			i += 2
		case '`':
			return i + 1
		case '$':
			if i+1 < n && runes[i+1] == '{' {
				// Skip the interpolation expression.
				depth := 1
				i += 2
				for i < n && depth > 0 {
					switch runes[i] {
					case '{':
						depth++
						i++
					case '}':
						depth--
						i++
					case '"', '\'':
						q := runes[i]
						i++
						for i < n && runes[i] != q && runes[i] != '\n' {
							if runes[i] == '\\' {
								i++
							}
							i++
						}
						if i < n {
							i++
						}
					case '`':
						i = skipTemplate(runes, i)
					default:
						i++
					}
				}
			} else {
				i++
			}
		default:
			i++
		}
	}
	return n
}

var _ = utf8.RuneLen
EOF
