package js

// importRecord is a single module reference in a JS/TS file.
type importRecord struct {
	source     string
	names      []string // imported symbol names, when specific
	generic    bool     // namespace / side-effect / require / dynamic
	dependency bool     // false for `export * from ...`
	exportFrom bool
}

type exportRecord struct {
	exported string
	original string
	source   string
	hasFrom  bool
}

type parsedFile struct {
	records []importRecord
	exports []exportRecord
}

// parseJS extracts import/export records from tokenized source.
func parseJS(src string) *parsedFile {
	toks := tokenizeJS(src)
	pf := &parsedFile{}
	for i := 0; i < len(toks); i++ {
		t := toks[i]
		if t.kind != tIdent {
			continue
		}
		switch t.val {
		case "import":
			if rec, ok := parseImportDecl(toks, i); ok {
				pf.records = append(pf.records, rec)
			}
		case "export":
			recs, exps := parseExportDecl(toks, i)
			pf.records = append(pf.records, recs...)
			pf.exports = append(pf.exports, exps...)
		case "require":
			// require('...') — but not obj.require('...')
			if i > 0 && toks[i-1].val == "." {
				continue
			}
			if i+2 < len(toks) && toks[i+1].val == "(" && toks[i+2].kind == tString {
				pf.records = append(pf.records, importRecord{source: toks[i+2].val, generic: true, dependency: true})
			}
		}
	}
	return pf
}

func parseImportDecl(toks []token, i int) (importRecord, bool) {
	// import(...)
	if i+1 < len(toks) && toks[i+1].val == "(" {
		if i+2 < len(toks) && toks[i+2].kind == tString {
			return importRecord{source: toks[i+2].val, generic: true, dependency: true}, true
		}
		return importRecord{}, false
	}
	// import.meta
	if i+1 < len(toks) && toks[i+1].val == "." {
		return importRecord{}, false
	}
	// import '...'
	if i+1 < len(toks) && toks[i+1].kind == tString {
		return importRecord{source: toks[i+1].val, generic: true, dependency: true}, true
	}
	// import <clause> from '...'
	fromIdx := -1
	for j := i + 1; j < len(toks) && j < i+60; j++ {
		if toks[j].val == ";" {
			break
		}
		if toks[j].kind == tIdent && toks[j].val == "from" && j+1 < len(toks) && toks[j+1].kind == tString {
			fromIdx = j
			break
		}
	}
	if fromIdx < 0 {
		return importRecord{}, false
	}
	clause := toks[i+1 : fromIdx]
	names, generic := parseImportClause(clause)
	return importRecord{source: toks[fromIdx+1].val, names: names, generic: generic, dependency: true}, true
