// parseImportClause parses the binding clause of an import declaration.
func parseImportClause(clause []token) ([]string, bool) {
	// Strip a leading `type` modifier when followed by { or *.
	if len(clause) > 1 && clause[0].kind == tIdent && clause[0].val == "type" && (clause[1].val == "{" || clause[1].val == "*") {
		clause = clause[1:]
	}
	names := []string{}
	generic := false
	i := 0
	// Default import.
	if i < len(clause) && clause[i].kind == tIdent && clause[i].val != "type" {
		names = append(names, "default")
		i++
		if i < len(clause) && clause[i].val == "," {
			i++
		}
	} else if i < len(clause) && clause[i].kind == tIdent && clause[i].val == "type" && i+1 < len(clause) && clause[i+1].kind == tIdent {
