	var item []token
	flush := func() {
		if name, ok := namedItemName(item); ok {
			names = append(names, name)
		}
		item = nil
	}
	for _, t := range inner {
		if t.val == "," {
			flush()
			continue
		}
		item = append(item, t)
	}
	flush()
	return names
}

