type namedItem struct {
	original string
	alias    string
}

func parseNamedItems(toks []token) []namedItem {
	items := []namedItem{}
	start := -1
	for i, t := range toks {
		if t.val == "{" {
			start = i
			break
		}
	}
	if start < 0 {
		return items
	}
	depth := 0
	end := len(toks)
	for i := start; i < len(toks); i++ {
		if toks[i].val == "{" {
			depth++
		} else if toks[i].val == "}" {
			depth--
			if depth == 0 {
				end = i
				break
			}
		}
	}
	inner := toks[start+1 : end]
	var item []token
	flush := func() {
		if len(item) == 0 {
			return
		}
		// Skip a `type` modifier.
		if len(item) > 1 && item[0].val == "type" && !(item[1].val == "as" || item[1].val == "," || item[1].val == "}") {
			item = item[1:]
		}
		if len(item) == 0 {
			return
		}
		ni := namedItem{original: item[0].val, alias: item[0].val}
		for i := 0; i+2 < len(item); i++ {
			if item[i].val == "as" {
				ni.alias = item[i+1].val
				break
			}
		}
		items = append(items, ni)
		item = nil
	}
	for _, t := range inner {
		if t.val == "," {
			flush()
			continue
		}
		item = append(item, t)
	}
	flush()
	return items
}

