		}
		if hasFrom {
			names := []string{}
			for _, it := range items {
				names = append(names, it.original)
				exports = append(exports, exportRecord{exported: it.alias, original: it.original, source: src, hasFrom: true})
			}
			records = append(records, importRecord{source: src, names: names, dependency: true, exportFrom: true})
		} else {
			for _, it := range items {
				exports = append(exports, exportRecord{exported: it.alias, original: it.alias})
			}
		}
	case next.val == "default":
		exports = append(exports, exportRecord{exported: "default", original: "default"})
	default:
		// export <declaration>
		j := i + 1
		// Skip modifiers.
		for j < len(toks) && (toks[j].val == "declare" || toks[j].val == "abstract" || toks[j].val == "async") {
			j++
		}
		if j >= len(toks) {
			break
		}
		kw := toks[j].val
		switch kw {
		case "const", "let", "var":
			// Declarator names at the top level of the declaration.
			for _, name := range declaratorNames(toks[j+1:]) {
				exports = append(exports, exportRecord{exported: name, original: name})
			}
		case "function", "class", "interface", "type", "enum", "namespace", "module":
			k := j + 1
			if k < len(toks) && toks[k].val == "*" {
				k++
			}
			if k < len(toks) && toks[k].kind == tIdent {
				exports = append(exports, exportRecord{exported: toks[k].val, original: toks[k].val})
			}
		}
	}
	return records, exports
}

// declaratorNames extracts variable names from a var/let/const
// declaration token stream, stopping at the end of the declaration.
func declaratorNames(toks []token) []string {
	names := []string{}
	depth := 0
	expectName := true
	for i := 0; i < len(toks); i++ {
		t := toks[i]
		switch t.val {
		case "(", "[", "{":
			depth++
		case ")", "]", "}":
			depth--
		case ";":
			if depth <= 0 {
				return names
			}
		case ",":
			if depth == 0 {
				expectName = true
			}
		default:
			if expectName && depth == 0 && t.kind == tIdent {
				names = append(names, t.val)
				expectName = false
			} else if expectName && depth == 0 && (t.val == "{" || t.val == "[") {
				expectName = false
			}
		}
		if t.kind == tIdent && (t.val == "export" || t.val == "import") && depth == 0 && i > 0 {
			// A following declaration started (semicolon-less style).
			return names
		}
	}
	return names
}
