	if err != nil {
		return nil, err
	}
	if contents == nil {
		contents, _ = os.ReadFile(abs)
	}
	root := p.root(abs)
	res := &langcore.Result{Info: langcore.Info{
		Abs:     abs,
		Display: langcore.RelativeDisplay(rootDir(root), abs),
		Group:   root.name,
		Loc:     langcore.Loc(contents),
	}}
	seen := map[string]bool{}
	add := func(dep string) {
		if dep == "" || dep == abs || seen[dep] {
			return
		}
		seen[dep] = true
		res.Deps = append(res.Deps, dep)
	}
	seenErr := map[string]bool{}
	addErr := func(e string) {
		if e == "" || seenErr[e] {
			return
		}
		seenErr[e] = true
		res.Errors = append(res.Errors, e)
	}
