func (p *Parser) resolveWorkspace(importer, spec string) (string, string, bool) {
	ws := p.workspaceRoot(importer)
	if ws == nil {
		return "", "", false
	}
	pkgName, rest := splitPackageSpec(spec)
	pkg, ok := ws.packages[pkgName]
	if !ok {
		return "", "", false
	}
	if rest == "" {
		if pkg.main != "" {
			if f, ok := resolveFileOrDir(filepath.Join(pkg.dir, pkg.main)); ok {
				return f, "", true
			}
			return "", fmt.Sprintf("workspace '%s' has no index file", pkg.dir), true
		}
		if f, ok := resolveFileOrDir(pkg.dir); ok {
			return f, "", true
		}
		return "", fmt.Sprintf("workspace '%s' has no index file", pkg.dir), true
	}
	candidate := filepath.Join(pkg.dir, filepath.FromSlash(rest))
	if f, ok := resolveFileOrDir(candidate); ok {
		return f, "", true
	}
	return "", fmt.Sprintf("path '%s' matched workspace '%s', but no file '%s' does not exist", spec, pkgName, candidate), true
}

func splitPackageSpec(spec string) (string, string) {
	parts := strings.Split(spec, "/")
	if strings.HasPrefix(spec, "@") && len(parts) >= 2 {
		name := parts[0] + "/" + parts[1]
		return name, strings.Join(parts[2:], "/")
	}
	return parts[0], strings.Join(parts[1:], "/")
}

// expandWorkspaceDirs returns directories under root matching a
// workspace glob pattern, in lexical order.
func expandWorkspaceDirs(root, pattern string) []string {
	pattern = filepath.ToSlash(pattern)
	if !dstar.HasMagic(pattern) {
		dir := filepath.Join(root, filepath.FromSlash(pattern))
		if langcore.IsDir(dir) {
			return []string{dir}
		}
		return nil
	}
	var dirs []string
	_ = filepath.WalkDir(root, func(path string, d os.DirEntry, err error) error {
		if err != nil {
			return nil
		}
		if d.IsDir() {
			if d.Name() == "node_modules" || d.Name() == ".git" {
				return filepath.SkipDir
			}
			rel, rerr := filepath.Rel(root, path)
			if rerr == nil && rel != "." {
				if dstar.Match(pattern, filepath.ToSlash(rel)) {
					dirs = append(dirs, path)
				}
			}
		}
		return nil
	})
	sort.Strings(dirs)
	return dirs
}
