// Options controls the JavaScript/TypeScript parser.
type Options struct {
	UnwrapExports bool
	Workspaces    bool
	TsConfigPaths bool
}

// Parser parses JS/TS files.
type Parser struct {
	opts     Options
	cache    map[string]*parsedFile
	rootFor  map[string]rootInfo
	tsCache  map[string]*tsConfigResult
	wsCache  map[string]*workspaceSet
}

type rootInfo struct {
	dir  string
	name string
	ok   bool
}

// NewParser creates a JS/TS parser.
func NewParser(opts Options) *Parser {
	return &Parser{
		opts:    opts,
		cache:   map[string]*parsedFile{},
		rootFor: map[string]rootInfo{},
		tsCache: map[string]*tsConfigResult{},
		wsCache: map[string]*workspaceSet{},
	}
}

var extOrder = []string{".js", ".ts", ".tsx", ".jsx", ".d.ts", ".mjs", ".cjs"}

var knownExts = map[string]bool{
	".js": true, ".ts": true, ".tsx": true, ".jsx": true, ".mjs": true, ".cjs": true,
}

func (p *Parser) root(abs string) rootInfo {
	dir := filepath.Dir(abs)
	if r, ok := p.rootFor[dir]; ok {
		return r
	}
	d, name, found := langcore.NamedPackageRoot(dir)
	r := rootInfo{dir: d, name: name, ok: found}
	p.rootFor[dir] = r
	return r
}

func (p *Parser) parse(abs string) (*parsedFile, []byte, error) {
	if pf, ok := p.cache[abs]; ok {
		return pf, nil, nil
	}
	contents, err := os.ReadFile(abs)
	if err != nil {
		return nil, nil, err
	}
	pf := parseJS(string(contents))
	p.cache[abs] = pf
	return pf, contents, nil
}

// Parse parses a JS/TS file.
func (p *Parser) Parse(abs string) (*langcore.Result, error) {
	pf, contents, err := p.parse(abs)
	if err != nil {
		return nil, err
	}
	if contents == nil {
		contents, _ = os.ReadFile(abs)
	}
	root := p.root(abs)
	res := &langcore.Result{Info: langcore.Info{
		Abs:     abs,
		Display: langcore.RelativeDisplay(rootDir(root), abs),
		Group:   root.name,
		Loc:     langcore.Loc(contents),
	}}
	seen := map[string]bool{}
	add := func(dep string) {
		if dep == "" || dep == abs || seen[dep] {
			return
		}
		seen[dep] = true
		res.Deps = append(res.Deps, dep)
	}
	seenErr := map[string]bool{}
	addErr := func(e string) {
		if e == "" || seenErr[e] {
			return
		}
		seenErr[e] = true
		res.Errors = append(res.Errors, e)
	}
	for _, rec := range pf.records {
		if !rec.dependency {
			continue
		}
		target, errStr := p.resolveSource(abs, rec.source)
		if errStr != "" {
			addErr(errStr)
			continue
		}
		if target == "" {
			continue
		}
		if !p.opts.UnwrapExports {
			add(target)
			continue
		}
		for _, dep := range p.unwrap(target, rec, map[string]bool{}) {
			add(dep)
		}
	}
	return res, nil
}

func rootDir(r rootInfo) string {
	if !r.ok {
		return ""
	}
	return r.dir
}

// resolveSource resolves a module specifier to a local file, returning
// an error string when resolution was attempted but failed.
func (p *Parser) resolveSource(importer, spec string) (string, string) {
	if strings.HasPrefix(spec, "./") || strings.HasPrefix(spec, "../") || spec == "." || spec == ".." {
		target := filepath.Join(filepath.Dir(importer), spec)
		if f, ok := resolveFileOrDir(target); ok {
			return f, ""
		}
		return "", fmt.Sprintf("could not perform relative import for '%s' because the file or dir was not found", spec)
	}
	if p.opts.Workspaces {
		if f, errStr, matched := p.resolveWorkspace(importer, spec); matched {
			return f, errStr
		}
	}
	if p.opts.TsConfigPaths {
		if f, errStr := p.resolveTsConfig(importer, spec); errStr != "" || f != "" {
			return f, errStr
		}
	}
	return "", ""
}

// resolveFileOrDir resolves a filesystem path to a concrete JS/TS file.
func resolveFileOrDir(target string) (string, bool) {
	if langcore.IsDir(target) {
		for _, ext := range extOrder {
			candidate := filepath.Join(target, "index"+ext)
			if langcore.IsFile(candidate) {
				return candidate, true
			}
		}
		return "", false
	}
	base := target
	if ext := filepath.Ext(target); knownExts[ext] {
		base = strings.TrimSuffix(target, ext)
	}
	for _, ext := range extOrder {
		candidate := base + ext
		if langcore.IsFile(candidate) {
			return candidate, true
		}
	}
	return "", false
