// ---- re-export unwrapping ----

func (p *Parser) unwrap(target string, rec importRecord, visited map[string]bool) []string {
	if !rec.generic && len(rec.names) > 0 {
		out := []string{}
		for _, name := range rec.names {
			out = append(out, p.unwrapName(target, name, visited)...)
		}
		return out
	}
	return p.unwrapAll(target, visited)
}

func (p *Parser) unwrapName(target, name string, visited map[string]bool) []string {
	key := target + "\x00" + name
	if visited[key] {
		return nil
	}
	visited[key] = true
	defer delete(visited, key)
	pf, _, err := p.parse(target)
	if err != nil {
		return nil
	}
	var star *exportRecord
	for i, exp := range pf.exports {
		if exp.exported == name {
			return p.resolveExport(target, &pf.exports[i], visited)
		}
		if exp.exported == "*" {
			star = &pf.exports[i]
		}
	}
	if star != nil {
		sourceFile, _ := p.resolveSource(target, star.source)
		if sourceFile == "" {
			return nil
		}
		return p.unwrapName(sourceFile, name, visited)
	}
	return nil
}

func (p *Parser) unwrapAll(target string, visited map[string]bool) []string {
	key := target + "\x00*"
	if visited[key] {
		return nil
	}
	visited[key] = true
	defer delete(visited, key)
	pf, _, err := p.parse(target)
	if err != nil || len(pf.exports) == 0 {
		return nil
	}
	out := []string{}
	for i := range pf.exports {
		out = append(out, p.resolveExport(target, &pf.exports[i], visited)...)
	}
	return out
}

func (p *Parser) resolveExport(owner string, exp *exportRecord, visited map[string]bool) []string {
	if !exp.hasFrom {
		return []string{owner}
	}
	sourceFile, _ := p.resolveSource(owner, exp.source)
	if sourceFile == "" {
		return nil
	}
	if exp.exported == "*" && exp.original == "*" {
		return p.unwrapAll(sourceFile, visited)
	}
	if exp.original == "*" {
		return []string{sourceFile}
	}
	return p.unwrapName(sourceFile, exp.original, visited)
