// ---- workspaces ----

type workspacePackage struct {
	dir  string
	name string
	main string
}

type workspaceSet struct {
	root     string
	packages map[string]*workspacePackage
}

func (p *Parser) workspaceRoot(importer string) *workspaceSet {
	startDir := filepath.Dir(importer)
	if ws, ok := p.wsCache[startDir]; ok {
		return ws
	}
	var found *workspaceSet
	dir := startDir
	for {
		if pkg, ok := readPackageFile(dir); ok && pkg.hasWorkspaces {
			found = &workspaceSet{root: dir, packages: map[string]*workspacePackage{}}
			for _, pattern := range pkg.workspacePatterns {
				for _, pkgDir := range expandWorkspaceDirs(dir, pattern) {
					if sub, ok := readPackageFile(pkgDir); ok && sub.name != "" {
						if _, exists := found.packages[sub.name]; !exists {
							found.packages[sub.name] = &workspacePackage{dir: pkgDir, name: sub.name, main: sub.main}
						}
					}
				}
			}
			break
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			break
		}
		dir = parent
	}
	p.wsCache[startDir] = found
	return found
}

func (p *Parser) resolveWorkspace(importer, spec string) (string, string, bool) {
	ws := p.workspaceRoot(importer)
	if ws == nil {
		return "", "", false
	}
	pkgName, rest := splitPackageSpec(spec)
	pkg, ok := ws.packages[pkgName]
	if !ok {
		return "", "", false
	}
	if rest == "" {
		if pkg.main != "" {
			if f, ok := resolveFileOrDir(filepath.Join(pkg.dir, pkg.main)); ok {
				return f, "", true
			}
			return "", fmt.Sprintf("workspace '%s' has no index file", pkg.dir), true
		}
		if f, ok := resolveFileOrDir(pkg.dir); ok {
			return f, "", true
		}
		return "", fmt.Sprintf("workspace '%s' has no index file", pkg.dir), true
	}
	candidate := filepath.Join(pkg.dir, filepath.FromSlash(rest))
	if f, ok := resolveFileOrDir(candidate); ok {
		return f, "", true
	}
	return "", fmt.Sprintf("path '%s' matched workspace '%s', but no file '%s' does not exist", spec, pkgName, candidate), true
}

func splitPackageSpec(spec string) (string, string) {
	parts := strings.Split(spec, "/")
	if strings.HasPrefix(spec, "@") && len(parts) >= 2 {
		name := parts[0] + "/" + parts[1]
		return name, strings.Join(parts[2:], "/")
	}
	return parts[0], strings.Join(parts[1:], "/")
}

