package js

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

// CompilerOptions mirrors the tsconfig compilerOptions we care about.
type CompilerOptions struct {
	BaseURL string              `json:"baseUrl"`
	Paths   map[string][]string `json:"paths"`
}

type tsConfigFile struct {
	CompilerOptions CompilerOptions `json:"compilerOptions"`
}

type tsConfigResult struct {
	cfg    *tsConfigFile
	err    string
	absDir string
	exists bool
}

func (p *Parser) tsConfigFor(importer string) *tsConfigResult {
	root := p.root(importer)
	dir := rootDir(root)
	if dir == "" {
		if cwd, err := os.Getwd(); err == nil {
			dir = cwd
		} else {
			dir = filepath.Dir(importer)
		}
	}
	if res, ok := p.tsCache[dir]; ok {
		return res
	}
	res := &tsConfigResult{absDir: dir}
	path := filepath.Join(dir, "tsconfig.json")
	data, err := os.ReadFile(path)
	if err == nil {
		res.exists = true
		var cfg tsConfigFile
		if jerr := json.Unmarshal(stripJSONC(data), &cfg); jerr != nil {
			res.err = fmt.Sprintf("found TypeScript config file in %s but there was an error reading it: %s", path, jerr.Error())
		} else {
			res.cfg = &cfg
		}
	}
	p.tsCache[dir] = res
	return res
}

func (p *Parser) resolveTsConfig(importer, spec string) (string, string) {
	res := p.tsConfigFor(importer)
	if !res.exists {
		return "", ""
	}
	if res.err != "" {
		return "", res.err
	}
	cfg := res.cfg
	baseDir := res.absDir
	if cfg.CompilerOptions.BaseURL != "" {
		baseDir = filepath.Join(res.absDir, filepath.FromSlash(cfg.CompilerOptions.BaseURL))
	}
	// Try path mappings, most specific first.
	type mapping struct {
		pattern string
		targets []string
		prefix  string
		suffix  string
		exact   bool
	}
	var mappings []mapping
	for pattern, targets := range cfg.CompilerOptions.Paths {
		m := mapping{pattern: pattern, targets: targets}
		if idx := strings.Index(pattern, "*"); idx >= 0 {
			m.prefix = pattern[:idx]
			m.suffix = pattern[idx+1:]
		} else {
			m.exact = true
			m.prefix = pattern
		}
		mappings = append(mappings, m)
	}
	sort.Slice(mappings, func(i, j int) bool {
		if mappings[i].exact != mappings[j].exact {
			return mappings[i].exact
		}
		if len(mappings[i].prefix) != len(mappings[j].prefix) {
			return len(mappings[i].prefix) > len(mappings[j].prefix)
		}
		return mappings[i].pattern < mappings[j].pattern
	})
	for _, m := range mappings {
		var matched string
		if m.exact {
			if spec != m.pattern {
				continue
			}
		} else {
			if !strings.HasPrefix(spec, m.prefix) || !strings.HasSuffix(spec, m.suffix) || len(spec) < len(m.prefix)+len(m.suffix) {
				continue
			}
			matched = spec[len(m.prefix) : len(spec)-len(m.suffix)]
		}
		for _, target := range m.targets {
			substituted := target
			if strings.Contains(target, "*") {
				substituted = strings.Replace(target, "*", matched, 1)
			}
			candidate := filepath.Join(baseDir, filepath.FromSlash(substituted))
			if f, ok := resolveFileOrDir(candidate); ok {
				return f, ""
			}
		}
	}
	// Fall back to resolving relative to the base URL.
	candidate := filepath.Join(baseDir, filepath.FromSlash(spec))
	if f, ok := resolveFileOrDir(candidate); ok {
		return f, ""
	}
	return "", ""
}

// stripJSONC removes comments and trailing commas so the standard JSON
// parser can read JSON-with-comments config files.
func stripJSONC(data []byte) []byte {
	var out []rune
	runes := []rune(string(data))
	inString := false
	for i := 0; i < len(runes); i++ {
		r := runes[i]
		if inString {
			out = append(out, r)
			if r == '\\' && i+1 < len(runes) {
				out = append(out, runes[i+1])
				i++
			} else if r == '"' {
				inString = false
			}
			continue
		}
		switch {
		case r == '"':
			inString = true
			out = append(out, r)
		case r == '/' && i+1 < len(runes) && runes[i+1] == '/':
			for i < len(runes) && runes[i] != '\n' {
				i++
			}
			i-- // step back; loop will advance
		case r == '/' && i+1 < len(runes) && runes[i+1] == '*':
			i += 2
			for i+1 < len(runes) && !(runes[i] == '*' && runes[i+1] == '/') {
				i++
			}
			i++
		default:
			out = append(out, r)
		}
	}
	// Remove trailing commas.
	cleaned := []rune{}
	for i := 0; i < len(out); i++ {
		if out[i] == ',' {
			j := i + 1
			for j < len(out) && (out[j] == ' ' || out[j] == '\t' || out[j] == '\n' || out[j] == '\r') {
				j++
			}
			if j < len(out) && (out[j] == '}' || out[j] == ']') {
				continue
			}
		}
		cleaned = append(cleaned, out[i])
	}
	return []byte(string(cleaned))
}
