// Package golang implements the Go language parser.
package golang

import (
	"fmt"
	goast "go/ast"
	goparser "go/parser"
	gotoken "go/token"
	gotypes "go/types"
	"os"
	"path/filepath"
	"sort"
	"strconv"
	"strings"

	"deptree/internal/langcore"
)

// Parser parses Go files.
type Parser struct {
	fset    *gotoken.FileSet
	files   map[string]*fileCache
	roots   map[string]*rootInfo
	imports map[string]*typesPkg
}

type fileCache struct {
	file *goast.File
	err  error
}

type rootInfo struct {
	dir    string
	module string
}

type typesPkg struct {
	pkg *gotypes.Package
}

// NewParser creates a Go parser, locating the go.mod for firstFile.
func NewParser(firstFile string) (*Parser, error) {
	p := &Parser{
		fset:    gotoken.NewFileSet(),
		files:   map[string]*fileCache{},
		roots:   map[string]*rootInfo{},
		imports: map[string]*typesPkg{},
	}
	root := p.rootFor(firstFile)
	if root == nil {
		return nil, fmt.Errorf("no go.mod file found in any parent directory of %s", firstFile)
	}
	return p, nil
}

func (p *Parser) rootFor(abs string) *rootInfo {
	dir := filepath.Dir(abs)
	if r, ok := p.roots[dir]; ok {
		return r
	}
	cur := dir
	var found *rootInfo
	for {
		if langcore.IsFile(filepath.Join(cur, "go.mod")) {
			module := parseGoMod(filepath.Join(cur, "go.mod"))
			found = &rootInfo{dir: cur, module: *module}
			break
		}
		parent := filepath.Dir(cur)
		if parent == cur {
			break
		}
		cur = parent
	}
	p.roots[dir] = found
	return found
}

// parseGoMod returns the module path declared in a go.mod file.
func parseGoMod(path string) *string {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil
	}
	for _, line := range strings.Split(string(data), "\n") {
		line = strings.TrimSpace(line)
		if strings.HasPrefix(line, "//") {
			continue
		}
		fields := strings.Fields(line)
		if len(fields) >= 2 && fields[0] == "module" {
			m := strings.Trim(fields[1], "\"")
			return &m
		}
	}
	return nil
}

func (p *Parser) parseFile(abs string) (*goast.File, error) {
	if c, ok := p.files[abs]; ok {
		return c.file, c.err
	}
	f, err := goparser.ParseFile(p.fset, abs, nil, goparser.SkipObjectResolution)
	p.files[abs] = &fileCache{file: f, err: err}
	return f, err
}

func (p *Parser) display(abs string) string {
	root := p.rootFor(abs)
	if root == nil {
		return ""
	}
	return langcore.RelativeDisplay(root.dir, abs)
}

// packageGroup holds the parsed files of one package in a directory.
type packageGroup struct {
	name  string
	files []*goast.File
	paths []string
}

func (p *Parser) dirGroups(dir string) (map[string]*packageGroup, error) {
	f, err := os.Open(dir)
	if err != nil {
		return nil, err
	}
	infos, err := f.Readdir(-1)
	f.Close()
	if err != nil {
		return nil, err
	}
	names := []string{}
	for _, info := range infos {
		if !info.IsDir() && strings.HasSuffix(info.Name(), ".go") {
			names = append(names, info.Name())
		}
	}
	sort.Strings(names)
	groups := map[string]*packageGroup{}
	for _, name := range names {
		path := filepath.Join(dir, name)
		ast, err := p.parseFile(path)
		if err != nil {
			return nil, err
		}
		if ast == nil || ast.Name == nil {
			continue
		}
		pkgName := ast.Name.Name
		g, ok := groups[pkgName]
		if !ok {
			g = &packageGroup{name: pkgName}
			groups[pkgName] = g
		}
		g.files = append(g.files, ast)
		g.paths = append(g.paths, path)
	}
	return groups, nil
}

// Parse parses a Go file.
func (p *Parser) Parse(abs string) (*langcore.Result, error) {
	contents, err := os.ReadFile(abs)
	if err != nil {
		return nil, err
	}
	astFile, err := p.parseFile(abs)
	if err != nil {
		return nil, err
	}
	root := p.rootFor(abs)
	res := &langcore.Result{Info: langcore.Info{
		Abs:     abs,
		Display: p.display(abs),
		Group:   astFile.Name.Name,
		Package: astFile.Name.Name,
		Loc:     langcore.Loc(contents),
	}}
	if root == nil {
		return res, nil
	}
	// Validate local imports, collecting resolution errors.
	importErr := map[string]bool{}
	for _, imp := range astFile.Imports {
		path, _ := strconv.Unquote(imp.Path.Value)
		if !isLocalPath(root.module, path) {
			continue
		}
		dir := importDir(root, path)
		if _, err := p.dirGroups(dir); err != nil {
			if !importErr[err.Error()] {
				importErr[err.Error()] = true
				res.Errors = append(res.Errors, err.Error())
			}
		}
	}
	res.Deps = p.usedFiles(abs, astFile, root)
	return res, nil
}

func isLocalPath(module, path string) bool {
	return path == module || strings.HasPrefix(path, module+"/")
}

func importDir(root *rootInfo, path string) string {
	if path == root.module {
		return root.dir
	}
	return filepath.Join(root.dir, filepath.FromSlash(strings.TrimPrefix(path, root.module+"/")))
}

// usedFiles type-checks the file's package and returns the local files
// whose top-level declarations the file actually uses.
func (p *Parser) usedFiles(abs string, astFile *goast.File, root *rootInfo) []string {
	dir := filepath.Dir(abs)
	groups, err := p.dirGroupsQuiet(dir)
	if err != nil {
		return nil
	}
	group := groups[astFile.Name.Name]
	if group == nil {
		return nil
	}
	pkgPath := root.module
	if rel, rerr := filepath.Rel(root.dir, dir); rerr == nil && rel != "." {
		pkgPath = root.module + "/" + filepath.ToSlash(rel)
	}
	info := &gotypes.Info{Uses: map[*goast.Ident]gotypes.Object{}}
	conf := gotypes.Config{
		Importer:                 &importer{p: p, root: root},
		FakeImportC:              true,
		DisableUnusedImportCheck: true,
		Error:                    func(error) {},
	}
	_, _ = conf.Check(pkgPath, p.fset, group.files, info)
	// Collect identifiers used in this file, in source order.
	type use struct {
		offset int
		ident  *goast.Ident
		obj    gotypes.Object
	}
	var uses []use
	for ident, obj := range info.Uses {
		if obj == nil {
			continue
		}
		pos := p.fset.Position(ident.Pos())
		if pos.Filename != abs {
			continue
		}
		uses = append(uses, use{offset: pos.Offset, ident: ident, obj: obj})
	}
	sort.Slice(uses, func(i, j int) bool { return uses[i].offset < uses[j].offset })
	deps := []string{}
	seen := map[string]bool{}
	for _, u := range uses {
		if _, isPkg := u.obj.(*gotypes.PkgName); isPkg {
			continue
		}
		pkg := u.obj.Pkg()
		if pkg == nil || !isLocalPath(root.module, pkg.Path()) {
			continue
		}
		target := p.fset.Position(u.obj.Pos()).Filename
		if target == "" || target == abs || seen[target] {
			continue
		}
		seen[target] = true
		deps = append(deps, target)
	}
	return deps
}

// dirGroupsQuiet is dirGroups but tolerant of broken sibling files.
func (p *Parser) dirGroupsQuiet(dir string) (map[string]*packageGroup, error) {
	infos, err := os.ReadDir(dir)
	if err != nil {
		return nil, err
	}
	groups := map[string]*packageGroup{}
	for _, info := range infos {
		if info.IsDir() || !strings.HasSuffix(info.Name(), ".go") {
			continue
		}
		path := filepath.Join(dir, info.Name())
		ast, err := p.parseFile(path)
		if err != nil || ast == nil || ast.Name == nil {
			continue
		}
		pkgName := ast.Name.Name
		g, ok := groups[pkgName]
		if !ok {
			g = &packageGroup{name: pkgName}
			groups[pkgName] = g
		}
		g.files = append(g.files, ast)
		g.paths = append(g.paths, path)
	}
	return groups, nil
}

// importer implements types.Importer for local and external packages.
type importer struct {
	p     *Parser
	root  *rootInfo
	cache map[string]*gotypes.Package
}

func (im *importer) Import(path string) (*gotypes.Package, error) {
	if im.cache == nil {
		im.cache = map[string]*gotypes.Package{}
	}
	if pkg, ok := im.cache[path]; ok {
		return pkg, nil
	}
	if isLocalPath(im.root.module, path) {
		dir := importDir(im.root, path)
		groups, err := im.p.dirGroupsQuiet(dir)
		if err != nil || len(groups) == 0 {
			pkg := gotypes.NewPackage(path, guessPkgName(path))
			im.cache[path] = pkg
			return pkg, fmt.Errorf("could not load package %s", path)
		}
		// Pick the non-test package when there are several.
		var group *packageGroup
		names := []string{}
		for name := range groups {
			names = append(names, name)
		}
		sort.Strings(names)
		for _, name := range names {
			if !strings.HasSuffix(name, "_test") {
				group = groups[name]
				break
			}
		}
		if group == nil {
			group = groups[names[0]]
		}
		// Placeholder first to break import cycles.
		placeholder := gotypes.NewPackage(path, group.name)
		im.cache[path] = placeholder
		sub := &importer{p: im.p, root: im.root, cache: im.cache}
		conf := gotypes.Config{Importer: sub, FakeImportC: true, DisableUnusedImportCheck: true, Error: func(error) {}}
		info := &gotypes.Info{}
		pkg, _ := conf.Check(path, im.p.fset, group.files, info)
		if pkg != nil {
			im.cache[path] = pkg
			return pkg, nil
		}
		return placeholder, nil
	}
	pkg := gotypes.NewPackage(path, guessPkgName(path))
	im.cache[path] = pkg
	return pkg, nil
}

func guessPkgName(path string) string {
	parts := strings.Split(path, "/")
	name := parts[len(parts)-1]
	if idx := strings.LastIndex(name, ".v"); idx > 0 {
		rest := name[idx+2:]
		isNum := rest != ""
		for _, r := range rest {
			if r < '0' || r > '9' {
				isNum = false
			}
		}
		if isNum {
			name = name[:idx]
		}
	}
	name = strings.ReplaceAll(name, "-", "_")
	return name
}

