}

func (im *importer) Import(path string) (*gotypes.Package, error) {
	if im.cache == nil {
		im.cache = map[string]*gotypes.Package{}
	}
	if pkg, ok := im.cache[path]; ok {
		return pkg, nil
	}
	if isLocalPath(im.root.module, path) {
		dir := importDir(im.root, path)
		groups, err := im.p.dirGroupsQuiet(dir)
		if err != nil || len(groups) == 0 {
			pkg := gotypes.NewPackage(path, guessPkgName(path))
