		var group *packageGroup
		names := []string{}
		for name := range groups {
			names = append(names, name)
		}
		sort.Strings(names)
		for _, name := range names {
			if !strings.HasSuffix(name, "_test") {
				group = groups[name]
				break
			}
		}
		if group == nil {
			group = groups[names[0]]
		}
