		conf := gotypes.Config{Importer: sub, FakeImportC: true, DisableUnusedImportCheck: true, Error: func(error) {}}
		info := &gotypes.Info{}
		pkg, _ := conf.Check(path, im.p.fset, group.files, info)
		if pkg != nil {
			im.cache[path] = pkg
			return pkg, nil
		}
		return placeholder, nil
	}
	pkg := gotypes.NewPackage(path, guessPkgName(path))
	im.cache[path] = pkg
	return pkg, nil
}

func guessPkgName(path string) string {
	parts := strings.Split(path, "/")
	name := parts[len(parts)-1]
	if idx := strings.LastIndex(name, ".v"); idx > 0 {
		rest := name[idx+2:]
		isNum := rest != ""
		for _, r := range rest {
			if r < '0' || r > '9' {
				isNum = false
			}
		}
		if isNum {
			name = name[:idx]
		}
	}
	name = strings.ReplaceAll(name, "-", "_")
	return name
}

