	for _, use := range stmts.uses {
		target, errStr, handled := p.resolveUse(abs, crate, use)
		if !handled {
			continue
		}
		if errStr != "" {
			res.Errors = append(res.Errors, errStr)
			continue
		}
		add(target)
	}
	res.Deps = deps
	return res, nil
}

func findModFile(dir, name string) (string, bool) {
	if f := filepath.Join(dir, name+".rs"); langcore.IsFile(f) {
		return f, true
	}
	if f := filepath.Join(dir, name, "mod.rs"); langcore.IsFile(f) {
		return f, true
	}
	return "", false
}

// ---- module tree ----

type modTree struct {
	rootFile string
	byChain  map[string]string // "a\x00b" -> file
	chainOf  map[string][]string
}

func chainKey(chain []string) string { return strings.Join(chain, "\x00") }

func (p *Parser) treeFor(crate *crateInfo) *modTree {
	if t, ok := p.trees[crate.dir]; ok {
		return t
	}
	t := &modTree{byChain: map[string]string{}, chainOf: map[string][]string{}}
	rootFile := findCrateRootFile(crate.dir)
	t.rootFile = rootFile
	if rootFile != "" {
		t.byChain[""] = rootFile
		t.chainOf[rootFile] = []string{}
		var walk func(file string, chain []string)
		walk = func(file string, chain []string) {
			contents, err := os.ReadFile(file)
			if err != nil {
				return
			}
			for _, mod := range scanRust(string(contents)).mods {
				child, ok := findModFile(filepath.Dir(file), mod)
				if !ok {
					continue
				}
				childChain := append(append([]string{}, chain...), mod)
				if _, exists := t.byChain[chainKey(childChain)]; exists {
					continue
				}
				t.byChain[chainKey(childChain)] = child
				t.chainOf[child] = childChain
				walk(child, childChain)
			}
		}
		walk(rootFile, []string{})
	}
	p.trees[crate.dir] = t
	return t
}

func findCrateRootFile(cargoDir string) string {
	for _, candidate := range []string{
		filepath.Join(cargoDir, "src", "lib.rs"),
		filepath.Join(cargoDir, "src", "main.rs"),
		filepath.Join(cargoDir, "lib.rs"),
		filepath.Join(cargoDir, "main.rs"),
	} {
		if langcore.IsFile(candidate) {
			return candidate
		}
	}
	return ""
}

func (p *Parser) resolveUse(abs string, crate *crateInfo, use rustUse) (string, string, bool) {
	if len(use.path) == 0 {
		return "", "", false
	}
	first := use.path[0]
	var base []string
	var rest []string
	tree := p.treeFor(crate)
	switch {
	case first == "crate":
		if tree.rootFile == "" {
			return "", fmt.Sprintf("error resolving use statement for name %s: main executable/library Rust file not found for cargo workspace in %s", use.name, crate.dir), true
		}
		base = []string{}
		rest = use.path[1:]
	case first == "self":
		chain, ok := tree.chainOf[abs]
		if !ok {
			if tree.rootFile == abs {
				chain = []string{}
			} else {
				chain = []string{}
			}
		}
		base = chain
		rest = use.path[1:]
	case first == "super":
		chain, _ := tree.chainOf[abs]
		count := 0
		for count < len(use.path) && use.path[count] == "super" {
			count++
		}
		if len(chain) < count {
			return "", fmt.Sprintf("error resolving use statement for name %s: could not find mod chain  in the projects mod tree", use.name), true
		}
		base = chain[:len(chain)-count]
		rest = use.path[count:]
	default:
		return "", "", false
	}
	if len(rest) == 0 {
		return "", "", true
	}
	name := rest[len(rest)-1]
	_ = name
	moduleSegs := rest[:len(rest)-1]
	desired := append(append([]string{}, base...), moduleSegs...)
	target, ok := tree.byChain[chainKey(desired)]
	if !ok {
		return "", fmt.Sprintf("error resolving use statement for name %s: could not find mod chain  in the projects mod tree", use.name), true
	}
	if target == abs {
		return "", "", true
	}
	return target, "", true
}
