package rust

import "strings"

type rustUse struct {
	path []string // full path segments, before any alias
	name string   // imported name (last segment, or alias target name)
}

type rustStmts struct {
	mods []string
	uses []rustUse
}

// scanRust extracts mod declarations and use statements.
func scanRust(src string) rustStmts {
	toks := lexRust(src)
	out := rustStmts{}
	for i := 0; i < len(toks); i++ {
		if toks[i] != "mod" && toks[i] != "use" {
			continue
		}
		// Must be at a statement position: previous token is one of
		// start, ';', '{', '}' or a visibility/attribute boundary.
		if toks[i] == "mod" {
			if i+2 < len(toks) && isRustIdent(toks[i+1]) && toks[i+2] == ";" {
				out.mods = append(out.mods, toks[i+1])
			}
			continue
		}
		// use: collect tokens up to ';'
		j := i + 1
		var stmt []string
		for j < len(toks) && toks[j] != ";" {
			stmt = append(stmt, toks[j])
			j++
		}
		out.uses = append(out.uses, expandUse(stmt)...)
		i = j
	}
	return out
}

func isRustIdent(s string) bool {
	if s == "" {
		return false
	}
	for i, r := range s {
		if r == '_' || (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') || r >= 0x80 || (i > 0 && r >= '0' && r <= '9') {
			continue
		}
		return false
	}
	switch s {
	case "mod", "use", "pub", "fn", "crate", "self", "super":
		// Keywords may still be path segments in use statements; for mod
		// names they cannot be keywords, but callers only check names.
	}
	return true
}

// expandUse expands a use statement token stream into individual paths.
func expandUse(toks []string) []rustUse {
	paths := expandUseTree(toks, nil)
	uses := []rustUse{}
	for _, p := range paths {
		if len(p) == 0 {
			continue
		}
		uses = append(uses, rustUse{path: p, name: p[len(p)-1]})
	}
	return uses
}

// expandUseTree parses a use tree and returns full segment paths.
func expandUseTree(toks []string, prefix []string) [][]string {
	// Split a leading path from any brace group.
	var results [][]string
	i := 0
	segments := append([]string{}, prefix...)
	for i < len(toks) {
		t := toks[i]
		if t == "::" {
			i++
			continue
		}
		if t == "{" {
			// Find matching brace and split its contents at commas.
			depth := 0
			end := i
			for ; end < len(toks); end++ {
				if toks[end] == "{" {
					depth++
				} else if toks[end] == "}" {
					depth--
					if depth == 0 {
						break
					}
				}
			}
			inner := toks[i+1 : end]
			for _, group := range splitTopLevel(inner) {
				results = append(results, expandUseTree(group, segments)...)
			}
			return results
		}
		if t == "as" {
			break
		}
		if t == "*" {
			segments = append(segments, "*")
			i++
			break
		}
		segments = append(segments, t)
		i++
	}
	if len(segments) > 0 {
		results = append(results, segments)
	}
	return results
}

func splitTopLevel(toks []string) [][]string {
	var groups [][]string
	var current []string
	depth := 0
	for _, t := range toks {
		if t == "{" {
			depth++
		} else if t == "}" {
			depth--
		}
		if t == "," && depth == 0 {
			if len(current) > 0 {
				groups = append(groups, current)
			}
			current = nil
			continue
		}
		current = append(current, t)
	}
	if len(current) > 0 {
		groups = append(groups, current)
	}
	return groups
}

// lexRust tokenizes Rust source, dropping comments and string contents.
func lexRust(src string) []string {
	var toks []string
	i := 0
	n := len(src)
	for i < n {
		c := src[i]
		switch {
		case c == ' ' || c == '\t' || c == '\n' || c == '\r':
			i++
		case c == '/' && i+1 < n && src[i+1] == '/':
			for i < n && src[i] != '\n' {
				i++
			}
		case c == '/' && i+1 < n && src[i+1] == '*':
			depth := 1
			i += 2
			for i < n && depth > 0 {
				if i+1 < n && src[i] == '/' && src[i+1] == '*' {
					depth++
					i += 2
				} else if i+1 < n && src[i] == '*' && src[i+1] == '/' {
					depth--
					i += 2
				} else {
					i++
				}
			}
		case c == '"':
			i = skipRustString(src, i)
			toks = append(toks, "STRING")
		case c == 'r' && i+1 < n && (src[i+1] == '"' || src[i+1] == '#'):
			// Raw string.
			j := i + 1
			hashes := 0
			for j < n && src[j] == '#' {
				hashes++
				j++
			}
			if j < n && src[j] == '"' {
				closing := "\"" + strings.Repeat("#", hashes)
				idx := strings.Index(src[j+1:], closing)
				if idx < 0 {
					i = n
				} else {
					i = j + 1 + idx + len(closing)
				}
				toks = append(toks, "STRING")
			} else {
				toks = append(toks, "r")
				i++
			}
		case c == '\'':
			// Char literal or lifetime.
			if i+2 < n && src[i+2] == '\'' {
				i += 3
				toks = append(toks, "CHAR")
			} else if i+3 < n && src[i+1] == '\\' && src[i+3] == '\'' {
				i += 4
				toks = append(toks, "CHAR")
			} else {
				toks = append(toks, "'")
				i++
			}
		case isRustIdent(string(c)) && (c == '_' || (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c >= 0x80):
			j := i + 1
			for j < n {
				d := src[j]
				if d == '_' || (d >= 'a' && d <= 'z') || (d >= 'A' && d <= 'Z') || (d >= '0' && d <= '9') || d >= 0x80 {
					j++
				} else {
					break
				}
			}
			toks = append(toks, src[i:j])
			i = j
		case c >= '0' && c <= '9':
			j := i + 1
			for j < n && (isAlnum(src[j]) || src[j] == '.') {
				j++
			}
			toks = append(toks, "NUMBER")
			i = j
		default:
			if c == ':' && i+1 < n && src[i+1] == ':' {
				toks = append(toks, "::")
				i += 2
			} else {
				toks = append(toks, string(c))
				i++
			}
		}
	}
	return toks
}

func isAlnum(c byte) bool {
	return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '_'
}

func skipRustString(src string, start int) int {
	i := start + 1
	for i < len(src) {
		if src[i] == '\\' {
			i += 2
			continue
		}
		if src[i] == '"' {
			return i + 1
		}
		i++
	}
	return len(src)
}
