)

// Parser parses Rust files.
type Parser struct {
	cargoDirs map[string]string
	crates    map[string]*crateInfo
	trees     map[string]*modTree
}

type crateInfo struct {
	dir  string
	name string
}

// NewParser creates a Rust parser.
func NewParser() *Parser {
	return &Parser{
		cargoDirs: map[string]string{},
		crates:    map[string]*crateInfo{},
		trees:     map[string]*modTree{},
	}
}

func (p *Parser) cargoDirFor(abs string) string {
	dir := filepath.Dir(abs)
	if d, ok := p.cargoDirs[dir]; ok {
		return d
	}
	found := langcore.FindMarkerRoot(dir, []string{"Cargo.toml"})
	p.cargoDirs[dir] = found
	return found
}

func (p *Parser) crateFor(abs string) *crateInfo {
	cargoDir := p.cargoDirFor(abs)
	if cargoDir == "" {
		return nil
	}
	if c, ok := p.crates[cargoDir]; ok {
		return c
	}
	c := &crateInfo{dir: cargoDir, name: parseCargoName(filepath.Join(cargoDir, "Cargo.toml"))}
	p.crates[cargoDir] = c
	return c
}

// parseCargoName extracts [package] name from a Cargo.toml file.
func parseCargoName(path string) string {
	data, err := os.ReadFile(path)
	if err != nil {
		return ""
	}
	section := ""
	for _, line := range strings.Split(string(data), "\n") {
		trimmed := strings.TrimSpace(line)
		if strings.HasPrefix(trimmed, "[") {
			section = trimmed
			continue
		}
		if section == "[package]" && strings.HasPrefix(trimmed, "name") {
			parts := strings.SplitN(trimmed, "=", 2)
			if len(parts) == 2 {
				return strings.Trim(strings.TrimSpace(parts[1]), "\"'")
			}
		}
	}
	return ""
}

// Parse parses a Rust file.
func (p *Parser) Parse(abs string) (*langcore.Result, error) {
	crate := p.crateFor(abs)
	if crate == nil {
		// Mirror the reference behaviour for Rust files that do not
		// belong to any Cargo project.
		var language *Parser
		_ = language.crateFor(abs)
	}
	contents, err := os.ReadFile(abs)
	if err != nil {
		return nil, err
	}
	root := crate.dir
	res := &langcore.Result{Info: langcore.Info{
		Abs:     abs,
		Display: langcore.RelativeDisplay(root, abs),
		Group:   crate.name,
		Loc:     langcore.Loc(contents),
	}}
	deps := []string{}
	seen := map[string]bool{}
	add := func(dep string) {
		if dep == "" || dep == abs || seen[dep] {
			return
		}
		seen[dep] = true
		deps = append(deps, dep)
	}
	stmts := scanRust(string(contents))
	// Module declarations resolve against the file's own directory.
	dir := filepath.Dir(abs)
	for _, mod := range stmts.mods {
		if f, ok := findModFile(dir, mod); ok {
			add(f)
		} else {
			res.Errors = append(res.Errors, fmt.Sprintf("could not find mod %s while looking in dir %s", mod, dir))
		}
	}
	// Use statements resolve against the crate's module tree.
	for _, use := range stmts.uses {
		target, errStr, handled := p.resolveUse(abs, crate, use)
		if !handled {
			continue
		}
		if errStr != "" {
			res.Errors = append(res.Errors, errStr)
			continue
		}
		add(target)
	}
	res.Deps = deps
	return res, nil
}

func findModFile(dir, name string) (string, bool) {
	if f := filepath.Join(dir, name+".rs"); langcore.IsFile(f) {
		return f, true
	}
	if f := filepath.Join(dir, name, "mod.rs"); langcore.IsFile(f) {
		return f, true
	}
	return "", false
}

