type modTree struct {
	rootFile string
	byChain  map[string]string // "a\x00b" -> file
	chainOf  map[string][]string
}

func chainKey(chain []string) string { return strings.Join(chain, "\x00") }

func (p *Parser) treeFor(crate *crateInfo) *modTree {
