				}
				childChain := append(append([]string{}, chain...), mod)
				if _, exists := t.byChain[chainKey(childChain)]; exists {
					continue
				}
				t.byChain[chainKey(childChain)] = child
				t.chainOf[child] = childChain
				walk(child, childChain)
			}
		}
		walk(rootFile, []string{})
	}
	p.trees[crate.dir] = t
	return t
}

func findCrateRootFile(cargoDir string) string {
	for _, candidate := range []string{
		filepath.Join(cargoDir, "src", "lib.rs"),
		filepath.Join(cargoDir, "src", "main.rs"),
		filepath.Join(cargoDir, "lib.rs"),
		filepath.Join(cargoDir, "main.rs"),
	} {
		if langcore.IsFile(candidate) {
			return candidate
		}
	}
	return ""
}

func (p *Parser) resolveUse(abs string, crate *crateInfo, use rustUse) (string, string, bool) {
	if len(use.path) == 0 {
		return "", "", false
	}
	first := use.path[0]
