		if !ok {
			if tree.rootFile == abs {
				chain = []string{}
			} else {
				chain = []string{}
			}
		}
		base = chain
		rest = use.path[1:]
	case first == "super":
		chain, _ := tree.chainOf[abs]
		count := 0
		for count < len(use.path) && use.path[count] == "super" {
			count++
		}
		if len(chain) < count {
			return "", fmt.Sprintf("error resolving use statement for name %s: could not find mod chain  in the projects mod tree", use.name), true
		}
		base = chain[:len(chain)-count]
		rest = use.path[count:]
	default:
		return "", "", false
	}
	if len(rest) == 0 {
		return "", "", true
	}
	name := rest[len(rest)-1]
	_ = name
	moduleSegs := rest[:len(rest)-1]
	desired := append(append([]string{}, base...), moduleSegs...)
	target, ok := tree.byChain[chainKey(desired)]
	if !ok {
		return "", fmt.Sprintf("error resolving use statement for name %s: could not find mod chain  in the projects mod tree", use.name), true
	}
	if target == abs {
		return "", "", true
	}
	return target, "", true
}
