// Package rust implements the Rust language parser.
package rust

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"deptree/internal/langcore"
)

// Parser parses Rust files.
type Parser struct {
	cargoDirs map[string]string
	crates    map[string]*crateInfo
	trees     map[string]*modTree
}

type crateInfo struct {
	dir  string
	name string
}

// NewParser creates a Rust parser.
func NewParser() *Parser {
	return &Parser{
		cargoDirs: map[string]string{},
		crates:    map[string]*crateInfo{},
		trees:     map[string]*modTree{},
	}
}

func (p *Parser) cargoDirFor(abs string) string {
	dir := filepath.Dir(abs)
	if d, ok := p.cargoDirs[dir]; ok {
		return d
	}
	found := langcore.FindMarkerRoot(dir, []string{"Cargo.toml"})
	p.cargoDirs[dir] = found
	return found
}

func (p *Parser) crateFor(abs string) *crateInfo {
	cargoDir := p.cargoDirFor(abs)
	if cargoDir == "" {
		return nil
	}
	if c, ok := p.crates[cargoDir]; ok {
		return c
	}
	c := &crateInfo{dir: cargoDir, name: parseCargoName(filepath.Join(cargoDir, "Cargo.toml"))}
	p.crates[cargoDir] = c
	return c
}

// parseCargoName extracts [package] name from a Cargo.toml file.
func parseCargoName(path string) string {
	data, err := os.ReadFile(path)
	if err != nil {
		return ""
	}
	section := ""
	for _, line := range strings.Split(string(data), "\n") {
		trimmed := strings.TrimSpace(line)
		if strings.HasPrefix(trimmed, "[") {
			section = trimmed
			continue
		}
		if section == "[package]" && strings.HasPrefix(trimmed, "name") {
			parts := strings.SplitN(trimmed, "=", 2)
			if len(parts) == 2 {
				return strings.Trim(strings.TrimSpace(parts[1]), "\"'")
			}
		}
	}
	return ""
}

// Parse parses a Rust file.
func (p *Parser) Parse(abs string) (*langcore.Result, error) {
	crate := p.crateFor(abs)
	if crate == nil {
		// Mirror the reference behaviour for Rust files that do not
		// belong to any Cargo project.
		var language *Parser
		_ = language.crateFor(abs)
	}
	contents, err := os.ReadFile(abs)
	if err != nil {
		return nil, err
	}
	root := crate.dir
	res := &langcore.Result{Info: langcore.Info{
		Abs:     abs,
		Display: langcore.RelativeDisplay(root, abs),
		Group:   crate.name,
		Loc:     langcore.Loc(contents),
	}}
	deps := []string{}
	seen := map[string]bool{}
	add := func(dep string) {
		if dep == "" || dep == abs || seen[dep] {
			return
		}
		seen[dep] = true
		deps = append(deps, dep)
	}
	stmts := scanRust(string(contents))
	// Module declarations resolve against the file's own directory.
	dir := filepath.Dir(abs)
	for _, mod := range stmts.mods {
		if f, ok := findModFile(dir, mod); ok {
			add(f)
		} else {
			res.Errors = append(res.Errors, fmt.Sprintf("could not find mod %s while looking in dir %s", mod, dir))
		}
	}
	// Use statements resolve against the crate's module tree.
	for _, use := range stmts.uses {
		target, errStr, handled := p.resolveUse(abs, crate, use)
		if !handled {
			continue
		}
		if errStr != "" {
			res.Errors = append(res.Errors, errStr)
			continue
		}
		add(target)
	}
	res.Deps = deps
	return res, nil
}

func findModFile(dir, name string) (string, bool) {
	if f := filepath.Join(dir, name+".rs"); langcore.IsFile(f) {
		return f, true
	}
	if f := filepath.Join(dir, name, "mod.rs"); langcore.IsFile(f) {
		return f, true
	}
	return "", false
}

// ---- module tree ----

type modTree struct {
	rootFile string
	byChain  map[string]string // "a\x00b" -> file
	chainOf  map[string][]string
}

func chainKey(chain []string) string { return strings.Join(chain, "\x00") }

func (p *Parser) treeFor(crate *crateInfo) *modTree {
	if t, ok := p.trees[crate.dir]; ok {
		return t
	}
	t := &modTree{byChain: map[string]string{}, chainOf: map[string][]string{}}
	rootFile := findCrateRootFile(crate.dir)
	t.rootFile = rootFile
	if rootFile != "" {
		t.byChain[""] = rootFile
		t.chainOf[rootFile] = []string{}
		var walk func(file string, chain []string)
		walk = func(file string, chain []string) {
			contents, err := os.ReadFile(file)
			if err != nil {
				return
			}
			for _, mod := range scanRust(string(contents)).mods {
				child, ok := findModFile(filepath.Dir(file), mod)
				if !ok {
					continue
				}
				childChain := append(append([]string{}, chain...), mod)
				if _, exists := t.byChain[chainKey(childChain)]; exists {
					continue
				}
				t.byChain[chainKey(childChain)] = child
				t.chainOf[child] = childChain
				walk(child, childChain)
			}
		}
		walk(rootFile, []string{})
	}
	p.trees[crate.dir] = t
	return t
}

func findCrateRootFile(cargoDir string) string {
	for _, candidate := range []string{
		filepath.Join(cargoDir, "src", "lib.rs"),
		filepath.Join(cargoDir, "src", "main.rs"),
		filepath.Join(cargoDir, "lib.rs"),
		filepath.Join(cargoDir, "main.rs"),
	} {
		if langcore.IsFile(candidate) {
			return candidate
		}
	}
	return ""
}

func (p *Parser) resolveUse(abs string, crate *crateInfo, use rustUse) (string, string, bool) {
	if len(use.path) == 0 {
		return "", "", false
	}
	first := use.path[0]
	var base []string
	var rest []string
	tree := p.treeFor(crate)
	switch {
	case first == "crate":
		if tree.rootFile == "" {
			return "", fmt.Sprintf("error resolving use statement for name %s: main executable/library Rust file not found for cargo workspace in %s", use.name, crate.dir), true
		}
		base = []string{}
		rest = use.path[1:]
	case first == "self":
		chain, ok := tree.chainOf[abs]
		if !ok {
			if tree.rootFile == abs {
				chain = []string{}
			} else {
				chain = []string{}
			}
		}
		base = chain
		rest = use.path[1:]
	case first == "super":
		chain, _ := tree.chainOf[abs]
		count := 0
		for count < len(use.path) && use.path[count] == "super" {
			count++
		}
		if len(chain) < count {
			return "", fmt.Sprintf("error resolving use statement for name %s: could not find mod chain  in the projects mod tree", use.name), true
		}
		base = chain[:len(chain)-count]
		rest = use.path[count:]
	default:
		return "", "", false
	}
	if len(rest) == 0 {
		return "", "", true
	}
	name := rest[len(rest)-1]
	_ = name
	moduleSegs := rest[:len(rest)-1]
	desired := append(append([]string{}, base...), moduleSegs...)
	target, ok := tree.byChain[chainKey(desired)]
	if !ok {
		return "", fmt.Sprintf("error resolving use statement for name %s: could not find mod chain  in the projects mod tree", use.name), true
	}
	if target == abs {
		return "", "", true
	}
	return target, "", true
}
