{"command":"cat > cmd/glob.go <<'EOF'
package cmd

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"deptree/internal/dstar"
)

// expandFileArgs expands command-line file arguments (glob patterns)
// into a flat list of absolute file paths.
func expandFileArgs(args []string) ([]string, [][]string, error) {
	all := []string{}
	perArg := [][]string{}
	for _, arg := range args {
		files, matched, badPattern := expandPattern(arg)
		if badPattern {
			return nil, nil, fmt.Errorf("syntax error in pattern")
		}
		if !matched {
			return nil, nil, fmt.Errorf("%s does not match with any existing file", arg)
		}
		perArg = append(perArg, files)
		all = append(all, files...)
	}
	if len(all) == 0 {
		return nil, nil, fmt.Errorf("no valid files where provided")
	}
	return all, perArg, nil
}

// expandPattern expands a single glob pattern. It reports whether any
// filesystem entry matched at all, and whether the pattern is invalid.
func expandPattern(pattern string) ([]string, bool, bool) {
	if pattern == "" {
		return nil, false, false
	}
	slashPattern := filepath.ToSlash(pattern)
	if !dstar.Validate(slashPattern) {
		return nil, false, true
	}
	if strings.HasSuffix(slashPattern, "/") && len(slashPattern) > 1 {
		return nil, false, false
	}
	cleaned := cleanPattern(slashPattern)
	if !dstar.HasMagic(cleaned) {
		info, err := os.Stat(filepath.FromSlash(cleaned))
		if err != nil {
			return nil, false, false
		}
		if info.IsDir() || !info.Mode().IsRegular() {
			return nil, true, false
		}
		abs, err := filepath.Abs(filepath.FromSlash(cleaned))
		if err != nil {
			return nil, true, false
		}
		return []string{abs}, true, false
	}
	// Magic pattern: walk the static prefix directory.
	segs := strings.Split(cleaned, "/")
	firstMagic := 0
	for i, s := range segs {
		if dstar.HasMagic(s) || s == "**" {
			firstMagic = i
			break
		}
	}
	absolute := strings.HasPrefix(cleaned, "/")
	var baseSegs []string
	if absolute {
		baseSegs = segs[1:firstMagic]
	} else {
		baseSegs = segs[:firstMagic]
	}
	basePath := ""
	if absolute {
		basePath = "/" + strings.Join(baseSegs, "/")
	} else if len(baseSegs) == 0 {
		basePath = "."
	} else {
		basePath = strings.Join(baseSegs, "/")
	}
	baseInfo, err := os.Stat(filepath.FromSlash(basePath))
	if err != nil {
		return nil, false, false
	}
	matched := false
	files := []string{}
	addCandidate := func(fsPath string) {
		logical := logicalPath(cleaned, fsPath)
		if !dstar.Match(cleaned, logical) {
			return
		}
		matched = true
		info, err := os.Stat(fsPath)
		if err != nil || info.IsDir() || !info.Mode().IsRegular() {
			return
		}
		abs, err := filepath.Abs(fsPath)
		if err == nil {
			files = append(files, abs)
		}
	}
	if !baseInfo.IsDir() {
		addCandidate(filepath.FromSlash(basePath))
		return files, matched, false
	}
	_ = filepath.WalkDir(filepath.FromSlash(basePath), func(path string, d os.DirEntry, err error) error {
		if err != nil {
			return nil
		}
		addCandidate(path)
		return nil
