package cmd

import (
	"fmt"
	"os"
	"strings"
	"time"
)

// progress renders a loading progress indicator to stderr, mimicking
// the behaviour of a terminal progress bar in non-terminal output.
type progress struct {
	start     time.Time
	current   int
	lastText  string
	started   bool
	finished  bool
	firstAdd  bool
}

func newProgress() *progress {
	p := &progress{start: time.Now(), firstAdd: true}
	p.renderInitial()
	return p
}

func (p *progress) rate(current int) string {
	elapsed := time.Since(p.start).Seconds()
	if current == 0 || elapsed <= 0 {
		return "(0 it/hr)"
	}
	rate := int(float64(current) / elapsed)
	if rate <= 0 {
		rate = 1
	}
	return fmt.Sprintf("(%d it/s)", rate)
}

func (p *progress) renderText(current, total int, desc string) string {
	var b strings.Builder
	b.WriteString("⠋ ")
	if total > 0 {
		b.WriteString(fmt.Sprintf("(%d/%d) ", current, total))
	}
	if desc != "" {
		b.WriteString(desc + " ")
	}
	if total <= 0 && desc == "" {
		b.WriteString(" ")
	}
	b.WriteString(p.rate(current))
	b.WriteString(" [0s] ")
	return b.String()
}

func (p *progress) write(text string) {
	fmt.Fprint(os.Stderr, "\r"+text)
	p.lastText = text
}

func (p *progress) renderInitial() {
	p.started = true
	text := p.renderText(0, 0, "")
	p.write(text)
}

func (p *progress) clear() {
	if p.lastText == "" {
		return
	}
	fmt.Fprint(os.Stderr, "\r"+strings.Repeat(" ", len([]rune(p.lastText)))+"\r")
}

// Add records one more loaded file.
func (p *progress) Add(current int, total int) {
	if p.finished {
		return
	}
	p.current = current
	if p.firstAdd {
		p.firstAdd = false
		// A first, description-less render precedes the counted ones.
		p.write(p.renderText(0, 0, ""))
		// Fix the rate display of that render to look like progress.
	}
	p.clear()
	p.write(p.renderText(current, total, "Loading Files..."))
	p.clear()
	p.write(p.renderText(current, total, "Loading Files..."))
}

// Finish renders the final state and a trailing newline.
func (p *progress) Finish(total int) {
	if p.finished {
		return
	}
	p.finished = true
	p.clear()
	p.write(p.renderText(p.current, total, "Finished loading"))
	p.clear()
	p.write(p.renderText(p.current, total, "Finished loading"))
	fmt.Fprint(os.Stderr, "\n")
}
EOF
cat > cmd/runtime.go <<'EOF'
package cmd

import (
	"path/filepath"

	"github.com/spf13/cobra"

	"deptree/internal/config"
	"deptree/internal/dstar"
	"deptree/internal/langcore"

	golang "deptree/internal/golang"
	jslang "deptree/internal/js"
	pythonlang "deptree/internal/python"
	rustlang "deptree/internal/rust"
)

// runtime bundles the loaded configuration and resolved settings for a
// single command execution.
type runtime struct {
	loaded        *config.Loaded
	unwrapExports bool
	jsWorkspaces  bool
	jsTsConfig    bool
	pyExcludeCond bool
	only          []string
	exclude       []string
}

func effectiveBool(cmd *cobra.Command, name string, cfgValue, def bool) bool {
	if cmd.Flags().Changed(name) {
		return cfgValue
	}
	return def
}

func loadRuntime(cmd *cobra.Command) (*runtime, error) {
	cfgPath, _ := cmd.Flags().GetString("config")
	changed := cmd.Flags().Changed("config")
	loaded, err := config.Load(cfgPath, changed)
	if err != nil {
		return nil, err
	}
	cfg := loaded.Config
	cliOnly, _ := cmd.Flags().GetStringArray("only")
	cliExclude, _ := cmd.Flags().GetStringArray("exclude")
	rt := &runtime{loaded: loaded}
	rt.unwrapExports = effectiveBool(cmd, "unwrap-exports", cfg.UnwrapExports, false)
	rt.jsWorkspaces = effectiveBool(cmd, "js-workspaces", cfg.Js.Workspaces, true)
	rt.jsTsConfig = effectiveBool(cmd, "js-tsconfig-paths", cfg.Js.TsConfigPaths, true)
	rt.pyExcludeCond = effectiveBool(cmd, "python-exclude-conditional-imports", cfg.Python.ExcludeConditionalImports, false)
	rt.only = append(append([]string{}, cfg.Only...), cliOnly...)
	rt.exclude = append(append([]string{}, cfg.Exclude...), cliExclude...)
	return rt, nil
}

// ignore reports whether a file is filtered out by only/exclude rules.
func (rt *runtime) ignore(abs string) bool {
	rel, err := filepath.Rel(rt.loaded.AbsDir(), abs)
	if err != nil {
		return false
	}
	rel = filepath.ToSlash(rel)
	if len(rt.only) > 0 {
		matched := false
		for _, pattern := range rt.only {
			if dstar.Match(filepath.ToSlash(pattern), rel) {
				matched = true
				break
			}
		}
		if !matched {
			return true
		}
	}
	for _, pattern := range rt.exclude {
		if dstar.Match(filepath.ToSlash(pattern), rel) {
			return true
		}
	}
	return false
}

// inferParser picks the language for the given files and builds a parser.
func (rt *runtime) inferParser(files []string) (langcore.Parser, error) {
	if len(files) == 0 {
		return nil, errAtLeastOneFile
	}
	kind := ""
	var first string
	for _, f := range files {
		k := languageKind(f)
		if k != "" {
			kind = k
			first = f
			break
		}
	}
	if kind == "" {
		return nil, errNoSupportedLanguage
	}
	switch kind {
	case "python":
		return pythonlang.NewParser(rt.pyExcludeCond), nil
	case "js":
		return jslang.NewParser(jslang.Options{
			UnwrapExports: rt.unwrapExports,
			Workspaces:    rt.jsWorkspaces,
			TsConfigPaths: rt.jsTsConfig,
		}), nil
	case "go":
		return golang.NewParser(first)
	case "rust":
		return rustlang.NewParser(), nil
	}
	return nil, errNoSupportedLanguage
}

func languageKind(path string) string {
	switch filepath.Ext(path) {
	case ".py":
		return "python"
	case ".js", ".ts", ".tsx", ".jsx", ".mjs", ".cjs", ".mts", ".cts":
		return "js"
	case ".go":
		return "go"
	case ".rs":
		return "rust"
	}
	return ""
}
