// inferParser picks the language for the given files and builds a parser.
func (rt *runtime) inferParser(files []string) (langcore.Parser, error) {
	if len(files) == 0 {
		return nil, errAtLeastOneFile
	}
	kind := ""
	var first string
	for _, f := range files {
		k := languageKind(f)
		if k != "" {
			kind = k
			first = f
			break
		}
	}
	if kind == "" {
		return nil, errNoSupportedLanguage
	}
	switch kind {
	case "python":
		return pythonlang.NewParser(rt.pyExcludeCond), nil
	case "js":
		return jslang.NewParser(jslang.Options{
			UnwrapExports: rt.unwrapExports,
			Workspaces:    rt.jsWorkspaces,
