		}), nil
	case "go":
		return golang.NewParser(first)
	case "rust":
		return rustlang.NewParser(), nil
	}
	return nil, errNoSupportedLanguage
}

func languageKind(path string) string {
	switch filepath.Ext(path) {
	case ".py":
		return "python"
	case ".js", ".ts", ".tsx", ".jsx", ".mjs", ".cjs", ".mts", ".cts":
