package cmd

import (
	"fmt"
	"os"
	"strings"
	"time"
)

// progress renders a loading progress indicator to stderr, mimicking
// the behaviour of a terminal progress bar in non-terminal output.
type progress struct {
	start     time.Time
	current   int
	lastText  string
	started   bool
	finished  bool
	firstAdd  bool
}

func newProgress() *progress {
	p := &progress{start: time.Now(), firstAdd: true}
	p.renderInitial()
	return p
}

func (p *progress) rate(current int) string {
	elapsed := time.Since(p.start).Seconds()
	if current == 0 || elapsed <= 0 {
		return "(0 it/hr)"
	}
	rate := int(float64(current) / elapsed)
	if rate <= 0 {
		rate = 1
	}
	return fmt.Sprintf("(%d it/s)", rate)
}

func (p *progress) renderText(current, total int, desc string) string {
	var b strings.Builder
	b.WriteString("⠋ ")
	if total > 0 {
		b.WriteString(fmt.Sprintf("(%d/%d) ", current, total))
	}
	if desc != "" {
		b.WriteString(desc + " ")
	}
	if total <= 0 && desc == "" {
		b.WriteString(" ")
	}
	b.WriteString(p.rate(current))
	b.WriteString(" [0s] ")
	return b.String()
}

func (p *progress) write(text string) {
	fmt.Fprint(os.Stderr, "\r"+text)
	p.lastText = text
}

func (p *progress) renderInitial() {
	p.started = true
	text := p.renderText(0, 0, "")
	p.write(text)
}

func (p *progress) clear() {
	if p.lastText == "" {
		return
	}
	fmt.Fprint(os.Stderr, "\r"+strings.Repeat(" ", len([]rune(p.lastText)))+"\r")
}

// Add records one more loaded file.
func (p *progress) Add(current int, total int) {
	if p.finished {
		return
	}
	p.current = current
	if p.firstAdd {
		p.firstAdd = false
		// A first, description-less render precedes the counted ones.
		p.write(p.renderText(0, 0, ""))
		// Fix the rate display of that render to look like progress.
	}
	p.clear()
	p.write(p.renderText(current, total, "Loading Files..."))
	p.clear()
	p.write(p.renderText(current, total, "Loading Files..."))
}

// Finish renders the final state and a trailing newline.
func (p *progress) Finish(total int) {
	if p.finished {
		return
	}
	p.finished = true
	p.clear()
	p.write(p.renderText(p.current, total, "Finished loading"))
	p.clear()
	p.write(p.renderText(p.current, total, "Finished loading"))
	fmt.Fprint(os.Stderr, "\n")
}
