		if k != "" {
			kind = k
			first = f
			break
		}
	}
	if kind == "" {
		return nil, errNoSupportedLanguage
	}
	switch kind {
	case "python":
		return pythonlang.NewParser(rt.pyExcludeCond), nil
	case "js":
		return jslang.NewParser(jslang.Options{
			UnwrapExports: rt.unwrapExports,
			Workspaces:    rt.jsWorkspaces,
			TsConfigPaths: rt.jsTsConfig,
		}), nil
	case "go":
		return golang.NewParser(first)
	case "rust":
		return rustlang.NewParser(), nil
	}
	return nil, errNoSupportedLanguage
}

func languageKind(path string) string {
	switch filepath.Ext(path) {
