	g, err := graph.Load(entrypoints, parser, rt.ignore, prog, graph.Options{})
	if err != nil {
		return err
	}
	for _, entry := range entrypoints {
		if g.Node(entry) == nil {
			return fmt.Errorf("could not find entrypoint %s", entry)
		}
	}
