package cmd

import (
	"fmt"
	"sort"

	"github.com/spf13/cobra"

	"deptree/internal/graph"
)

var explainCmd = &cobra.Command{
	Use:     "explain",
	GroupID: "explain",
	Short:   "Shows all the dependencies between two parts of the code",
	Args: func(cmd *cobra.Command, args []string) error {
		if len(args) != 2 {
			return fmt.Errorf("accepts 2 arg(s), received %d", len(args))
		}
		all, perArg, err := expandFileArgs(args)
		if err != nil {
			return err
		}
		expandedArgs = all
		perArgExpanded = perArg
		return nil
	},
	RunE: func(cmd *cobra.Command, args []string) error {
		return runExplain(cmd)
	},
}

func init() {
	explainCmd.Flags().BoolP("overlap-left", "l", false, "When there's an overlap between the files at the left and the right, keep the ones at the left")
	explainCmd.Flags().BoolP("overlap-right", "r", false, "When there's an overlap between the files at the left and the right, keep the ones at the right")
}

func dedupPreserve(list []string) []string {
	seen := map[string]bool{}
	out := []string{}
	for _, v := range list {
		if !seen[v] {
			seen[v] = true
			out = append(out, v)
		}
	}
	return out
}

func runExplain(cmd *cobra.Command) error {
	overlapLeft, _ := cmd.Flags().GetBool("overlap-left")
	overlapRight, _ := cmd.Flags().GetBool("overlap-right")
	if overlapLeft && overlapRight {
		return fmt.Errorf("only one of --overlap-left (-l) or --overlap-right (-r) can be used at a time")
	}
	rt, err := loadRuntime(cmd)
	if err != nil {
		return err
	}
	left := dedupPreserve(perArgExpanded[0])
	right := dedupPreserve(perArgExpanded[1])
	leftSet := map[string]bool{}
	for _, f := range left {
		leftSet[f] = true
	}
	rightSet := map[string]bool{}
	for _, f := range right {
		rightSet[f] = true
	}
	if overlapLeft || overlapRight {
		overlap := []string{}
		for _, f := range left {
			if rightSet[f] {
				overlap = append(overlap, f)
			}
		}
		overlapSet := map[string]bool{}
		for _, f := range overlap {
			overlapSet[f] = true
		}
		if overlapLeft {
			left = overlap
			newRight := []string{}
			for _, f := range right {
				if !overlapSet[f] {
					newRight = append(newRight, f)
				}
			}
			right = newRight
		} else {
			right = overlap
			newLeft := []string{}
			for _, f := range left {
				if !overlapSet[f] {
					newLeft = append(newLeft, f)
				}
			}
			left = newLeft
		}
		leftSet = map[string]bool{}
		for _, f := range left {
			leftSet[f] = true
		}
		rightSet = map[string]bool{}
		for _, f := range right {
			rightSet[f] = true
		}
	}
	parser, err := rt.inferParser(left)
	if err != nil {
		return err
	}
	input := dedupPreserve(append(append([]string{}, left...), right...))
	allowed := map[string]bool{}
	for _, f := range input {
		allowed[f] = true
	}
	prog := newProgress()
	g, err := graph.Load(input, parser, rt.ignore, prog, graph.Options{Fixed: true, Allowed: allowed})
	if err != nil {
		return err
	}
	lines := []string{}
	for _, node := range g.Nodes {
		if !leftSet[node.Info.Abs] {
			continue
		}
		for _, child := range g.Children(node) {
			if !rightSet[child.Info.Abs] {
				continue
			}
			lines = append(lines, formatExplainNode(node.Info)+" -> "+formatExplainNode(child.Info))
		}
	}
	sort.Strings(lines)
	for _, line := range lines {
		fmt.Println(line)
	}
	return nil
}
