	for _, f := range left {
		leftSet[f] = true
	}
	rightSet := map[string]bool{}
	for _, f := range right {
		rightSet[f] = true
	}
	if overlapLeft || overlapRight {
		overlap := []string{}
		for _, f := range left {
			if rightSet[f] {
				overlap = append(overlap, f)
			}
		}
		overlapSet := map[string]bool{}
		for _, f := range overlap {
			overlapSet[f] = true
		}
		if overlapLeft {
			left = overlap
			newRight := []string{}
			for _, f := range right {
				if !overlapSet[f] {
					newRight = append(newRight, f)
				}
			}
			right = newRight
		} else {
			right = overlap
			newLeft := []string{}
			for _, f := range left {
				if !overlapSet[f] {
					newLeft = append(newLeft, f)
				}
			}
			left = newLeft
		}
		leftSet = map[string]bool{}
		for _, f := range left {
