package cmd

import (
	"encoding/json"
	"sort"
	"strings"

	"deptree/internal/graph"
	"deptree/internal/langcore"
)

type entropyNode struct {
	ID           uint32   `json:"id"`
	IsEntrypoint bool     `json:"isEntrypoint"`
	FileName     string   `json:"fileName"`
	PathBuf      []string `json:"pathBuf"`
	Group        string   `json:"group,omitempty"`
	DirName      string   `json:"dirName"`
	Loc          int      `json:"loc"`
	Size         int      `json:"size"`
}

type entropyLink struct {
	From     uint32 `json:"from"`
	To       uint32 `json:"to"`
	IsCyclic bool   `json:"isCyclic"`
}

type entropyData struct {
	Nodes     []entropyNode `json:"nodes"`
	Links     []entropyLink `json:"links"`
	EnableGui bool          `json:"enableGui"`
}

func renderEntropyHTML(g *graph.Graph, entrypoints []string, enableGui bool) string {
	data := entropyData{Nodes: []entropyNode{}, Links: []entropyLink{}, EnableGui: enableGui}
	maxLoc := 0
	for _, n := range g.Nodes {
		if n.Info.Loc > maxLoc {
			maxLoc = n.Info.Loc
		}
	}
	singleEntry := ""
	if len(entrypoints) == 1 {
		singleEntry = entrypoints[0]
	}
	for _, n := range g.Nodes {
		fileName, dirName := langcore.DisplayParts(n.Info.Display)
		size := 0
		if maxLoc > 0 {
			size = 10 * n.Info.Loc / maxLoc
		}
		data.Nodes = append(data.Nodes, entropyNode{
			ID:           langcore.ID(n.Info.Abs),
			IsEntrypoint: singleEntry != "" && n.Info.Abs == singleEntry,
			FileName:     fileName,
			PathBuf:      langcore.SplitPathBuf(n.Info.Abs),
			Group:        n.Info.Group,
			DirName:      dirName,
			Loc:          n.Info.Loc,
			Size:         size,
		})
	}
	cyclic := cyclicEdges(g)
	for _, n := range g.Nodes {
		for _, child := range g.Children(n) {
			data.Links = append(data.Links, entropyLink{
				From:     langcore.ID(n.Info.Abs),
				To:       langcore.ID(child.Info.Abs),
				IsCyclic: cyclic[n.Info.Abs+"\x00"+child.Info.Abs],
			})
		}
	}
	payload, _ := json.Marshal(data)
	var b strings.Builder
	b.WriteString("<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\" />\n    <link\n            rel=\"icon\"\n            type=\"image/svg+xml\"\n            href=\"https://raw.githubusercontent.com/gabotechs/dep-tree/main/docs/dep-tree.svg\"\n    />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n    <title>Dep Tree</title>\n  </head>\n  <body>\n    <div id=\"root\"></div>\n    <script>\nfunction Jt(t,e,n){Object.defineProperty(t,e,{value:n});}\nclass KC{}\nJt(KC,\"__INLINE_DATA\",")
	b.Write(payload)
	b.WriteString(");\n")
	b.WriteString("document.getElementById('root').textContent = KC.__INLINE_DATA.nodes.map(function(n){return n.dirName + n.fileName;}).join('\\n');\n")
	b.WriteString("    </script>\n  </body>\n</html>\n")
	return b.String()
}

// cyclicEdges marks edges that point back to an ancestor in a DFS walk.
func cyclicEdges(g *graph.Graph) map[string]bool {
	cyclic := map[string]bool{}
	state := map[string]int{}
	var stack []*graph.Node
	var visit func(n *graph.Node)
	visit = func(n *graph.Node) {
		state[n.Info.Abs] = 1
		stack = append(stack, n)
		for _, child := range g.Children(n) {
			if state[child.Info.Abs] == 1 {
				cyclic[n.Info.Abs+"\x00"+child.Info.Abs] = true
			} else if state[child.Info.Abs] == 0 {
				visit(child)
			}
		}
		stack = stack[:len(stack)-1]
		state[n.Info.Abs] = 2
	}
	roots := append([]*graph.Node{}, g.Nodes...)
	sort.SliceStable(roots, func(i, j int) bool { return false })
	for _, n := range roots {
		if state[n.Info.Abs] == 0 {
			visit(n)
		}
	}
	return cyclic
}
