{"command":"rm cmd/tui_other.go
cat > cmd/tui_unix.go <<'EOF'
package cmd

import (
	"os"
	"strings"
	"syscall"
	"unsafe"

	"deptree/internal/graph"
)

type termios struct {
	Iflag  uint32
	Oflag  uint32
	Cflag  uint32
	Lflag  uint32
	Line   byte
	Cc     [32]byte
	Ispeed uint32
	Ospeed uint32
}

const ioctlReadTermios = 0x5401
const ioctlWriteTermios = 0x5402

func terminalError() string {
	term := os.Getenv("TERM")
	if term == "dumb" {
		return "terminal not cursor addressable"
	}
	if term == "" {
		return "exit status 1"
	}
	for _, prefix := range []string{"xterm", "screen", "tmux", "linux", "vt100", "rxvt", "ansi", "alacritty", "kitty", "wezterm", "st", "cygwin"} {
		if strings.HasPrefix(term, prefix) {
			return "open /dev/tty: no such device or address"
		}
	}
	return "exit status 1"
}

func terminalAvailable() bool {
	f, err := os.OpenFile("/dev/tty", os.O_RDWR, 0)
	if err != nil {
		return false
	}
	f.Close()
	return true
}

func makeRaw(f *os.File) (*termios, error) {
	var old termios
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, f.Fd(), uintptr(ioctlReadTermios), uintptr(unsafe.Pointer(&old)))
	if errno != 0 {
		return nil, errno
	}
	raw := old
	raw.Iflag &^= 0x1 | 0x2 | 0x10 | 0x20 | 0x40 | 0x100
	raw.Oflag &^= 0x1
	raw.Cflag &^= 0x100
	raw.Lflag &^= 0x8 | 0x2 | 0x1 | 0x8000
	raw.Cc[6] = 1  // VMIN
	raw.Cc[5] = 0  // VTIME
	_, _, errno = syscall.Syscall(syscall.SYS_IOCTL, f.Fd(), uintptr(ioctlWriteTermios), uintptr(unsafe.Pointer(&raw)))
	if errno != 0 {
		return nil, errno
	}
	return &old, nil
}

func restoreTerm(f *os.File, old *termios) {
	syscall.Syscall(syscall.SYS_IOCTL, f.Fd(), uintptr(ioctlWriteTermios), uintptr(unsafe.Pointer(old)))
}

func ttySize(f *os.File) (int, int) {
	type winsize struct {
		Row, Col, Xpixel, Ypixel uint16
	}
	var ws winsize
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, f.Fd(), uintptr(0x5413), uintptr(unsafe.Pointer(&ws)))
	if errno != 0 || ws.Col == 0 {
		return 80, 24
	}
	return int(ws.Col), int(ws.Row)
}

func runTUI(g *graph.Graph, entry string) error {
	tty, err := os.OpenFile("/dev/tty", os.O_RDWR, 0)
	if err != nil {
		return err
	}
	defer tty.Close()
	old, err := makeRaw(tty)
	if err != nil {
		return err
	}
	defer restoreTerm(tty, old)
	view := newTreeView(g, entry)
	// Enter the alternate screen.
	tty.WriteString("\x1b[?1049h\x1b[?25l")
	defer tty.WriteString("\x1b[?25h\x1b[?1049l")
	width, height := ttySize(tty)
	view.render(tty, width, height)
	buf := make([]byte, 64)
	for {
		n, err := tty.Read(buf)
		if err != nil {
			return err
		}
		if n == 0 {
			continue
		}
		quit, redraw := view.handleKey(buf[:n])
		if quit {
			return nil
		}
		if redraw {
			width, height = ttySize(tty)
			view.render(tty, width, height)
		}
	}
}
EOF
