{"command":"cat > cmd/tui_view.go <<'EOF'
package cmd

import (
	"fmt"
	"os"
	"strings"

	"deptree/internal/graph"
)

type cell struct {
	ch    rune
	color int // 0 default, 32 green, 36 cyan
	mask  int
	line  bool
	edges map[int]bool
	text  bool
	owner string // node abs for text cells
	tri   bool
}

const (
	dirN = 1
	dirS = 2
	dirW = 4
	dirE = 8
)

type visualRow struct {
	cells []*cell
	node  string
	plain string
}

type treeFrame struct {
	root   string
	cursor int
	top    int
}

type treeView struct {
	g          *graph.Graph
	frames     []treeFrame
	rows       []visualRow
	help       bool
	height     int
	cyclic     map[string]bool
}

func newTreeView(g *graph.Graph, entry string) *treeView {
	v := &treeView{g: g, cyclic: cyclicEdges(g)}
	v.frames = append(v.frames, treeFrame{root: entry})
	v.relayout()
	return v
}

func (v *treeView) frame() *treeFrame { return &v.frames[len(v.frames)-1] }

func (v *treeView) relayout() {
	v.rows = layoutGraph(v.g, v.frame().root, v.cyclic)
	fr := v.frame()
	if fr.cursor >= len(v.rows) {
		fr.cursor = len(v.rows) - 1
	}
	if fr.cursor < 0 {
		fr.cursor = 0
	}
}

func boxChar(mask int) rune {
	switch mask {
	case dirN | dirS:
		return '│'
	case dirW | dirE:
		return '─'
	case dirN | dirE:
		return '└'
	case dirS | dirE:
		return '┌'
	case dirS | dirW:
		return '┐'
	case dirN | dirW:
		return '┘'
	case dirN | dirS | dirE:
		return '├'
	case dirN | dirS | dirW:
		return '┤'
	case dirS | dirW | dirE:
		return '┬'
	case dirN | dirW | dirE:
		return '┴'
	case dirN | dirS | dirW | dirE:
		return '┼'
	case dirN:
		return '╵'
	case dirS:
		return '╷'
	case dirW:
		return '╴'
	case dirE:
		return '╶'
	}
	return ' '
}

// layoutGraph assigns coordinates to graph nodes and draws edges on a
// rune canvas.
func layoutGraph(g *graph.Graph, rootAbs string, cyclic map[string]bool) []visualRow {
	root := g.Node(rootAbs)
	if root == nil {
		return nil
	}
	// Nodes in BFS order, restricted to those reachable from root.
	order := []*graph.Node{}
	seen := map[string]bool{}
	queue := []*graph.Node{root}
	seen[root.Info.Abs] = true
	for len(queue) > 0 {
		n := queue[0]
		queue = queue[1:]
		order = append(order, n)
		for _, c := range g.Children(n) {
			if !seen[c.Info.Abs] {
				seen[c.Info.Abs] = true
				queue = append(queue, c)
			}
		}
	}
	indexOf := map[string]int{}
	for i, n := range order {
		indexOf[n.Info.Abs] = i
	}
	parents := map[string][]*graph.Node{}
	for _, n := range order {
		for _, c := range g.Children(n) {
			if seen[c.Info.Abs] {
				parents[c.Info.Abs] = append(parents[c.Info.Abs], n)
			}
		}
	}
	// Coordinates.
	xs := map[string]int{}
	ys := map[string]int{}
	maxEnd := 0
	for i, n := range order {
		if i == 0 {
			xs[n.Info.Abs] = 0
			ys[n.Info.Abs] = 0
		} else {
			prev := order[i-1]
			isChildOfPrev := false
			for _, p := range parents[n.Info.Abs] {
				if p == prev {
					isChildOfPrev = true
				}
			}
			if isChildOfPrev {
				ys[n.Info.Abs] = ys[prev.Info.Abs] + 2
			} else {
				ys[n.Info.Abs] = ys[prev.Info.Abs] + 1
			}
			candidate := 0
			for _, p := range parents[n.Info.Abs] {
				if px, ok := xs[p.Info.Abs]; ok && px+2 > candidate {
					candidate = px + 2
				}
			}
			// Bump for passing lines that occupy the text column.
			for {
				bumped := false
				for _, u := range order[:i] {
					for _, c := range g.Children(u) {
						if c == n {
							continue
						}
						if indexOf[c.Info.Abs] > i {
							if xs[u.Info.Abs] == candidate || xs[u.Info.Abs] == candidate-1 {
								candidate++
								bumped = true
							}
						}
					}
				}
				if !bumped {
					break
				}
			}
			xs[n.Info.Abs] = candidate
		}
		if end := xs[n.Info.Abs] + len([]rune(n.Info.Display)); end > maxEnd {
			maxEnd = end
		}
	}
	maxY := 0
	for _, n := range order {
		if ys[n.Info.Abs] > maxY {
			maxY = ys[n.Info.Abs]
		}
	}
	grid := map[int]map[int]*cell{}
	get := func(x, y int) *cell {
		row, ok := grid[y]
		if !ok {
			row = map[int]*cell{}
			grid[y] = row
		}
		c, ok := row[x]
		if !ok {
			c = &cell{ch: ' ', edges: map[int]bool{}}
			row[x] = c
		}
		return c
	}
	addLine := func(x, y, mask, edgeID int) {
		c := get(x, y)
		c.line = true
		c.mask |= mask
		c.edges[edgeID] = true
	}
	// Draw edges.
	edgeID := 0
	nodeByAbs := map[string]*graph.Node{}
	for _, n := range order {
		nodeByAbs[n.Info.Abs] = n
	}
	for _, n := range order {
		for _, child := range g.Children(n) {
			if !seen[child.Info.Abs] {
				continue
			}
			id := edgeID
			edgeID++
			px, py := xs[n.Info.Abs], ys[n.Info.Abs]
			cx, cy := xs[child.Info.Abs], ys[child.Info.Abs]
			isBack := cyclic[n.Info.Abs+"\x00"+child.Info.Abs] || cy <= py
			if isBack && child != n {
				rightCol := maxEnd
				if rightCol <= cx {
					rightCol = cx + 1
				}
				// Target marker and horizontal segment.
				tx := xs[child.Info.Abs] + len([]rune(child.Info.Display))
				marker := get(tx, cy)
				marker.ch = '◁'
				marker.tri = true
				marker.edges[id] = true
				for x := tx + 1; x < rightCol; x++ {
					addLine(x, cy, dirW|dirE, id)
				}
				addLine(rightCol, cy, dirS|dirW, id)
				for y := cy + 1; y < py; y++ {
					addLine(rightCol, y, dirN|dirS, id)
				}
				src := get(rightCol, py)
				src.line = true
				src.mask |= dirN | dirW
				src.edges[id] = true
				continue
			}
			tri := cx - 1
			for y := py + 1; y < cy; y++ {
				addLine(px, y, dirN|dirS, id)
			}
			// Child row.
			hasLaterChild := false
			for _, other := range g.Children(n) {
				if ys[other.Info.Abs] > cy {
					hasLaterChild = true
				}
			}
			mask := dirN
			if px < tri {
				mask |= dirE
			} else if px > tri {
				mask |= dirW
			}
			if hasLaterChild {
				mask |= dirS
			}
			addLine(px, cy, mask, id)
			if px < tri {
				for x := px + 1; x < tri; x++ {
					addLine(x, cy, dirW|dirE, id)
				}
			} else if px > tri {
				for x := tri + 1; x < px; x++ {
					addLine(x, cy, dirW|dirE, id)
				}
			}
			triCell := get(tri, cy)
			triCell.ch = '▷'
			triCell.tri = true
			triCell.edges[id] = true
		}
	}
	// Place node texts.
	for _, n := range order {
		x, y := xs[n.Info.Abs], ys[n.Info.Abs]
		for i, r := range []rune(n.Info.Display) {
			c := get(x+i, y)
			c.ch = r
			c.text = true
			c.owner = n.Info.Abs
			c.line = false
			c.mask = 0
		}
	}
	// Convert to rows.
	rows := []visualRow{}
	nodeAtY := map[int]string{}
	for _, n := range order {
		nodeAtY[ys[n.Info.Abs]] = n.Info.Abs
	}
	for y := 0; y <= maxY; y++ {
		rowCellsMap := grid[y]
		maxX := -1
		for x := range rowCellsMap {
			if x > maxX {
				maxX = x
			}
		}
		vr := visualRow{node: nodeAtY[y]}
		var plain strings.Builder
		for x := 0; x <= maxX; x++ {
			c := rowCellsMap[x]
			if c == nil {
				c = &cell{ch: ' ', edges: map[int]bool{}}
			}
			if c.line && !c.text && !c.tri {
				c.ch = boxChar(c.mask)
			}
			vr.cells = append(vr.cells, c)
			plain.WriteRune(c.ch)
		}
		vr.plain = strings.TrimRight(plain.String(), " ")
		vr.cells = vr.cells[:len([]rune(vr.plain))]
		rows = append(rows, vr)
	}
	return rows
}

func (v *treeView) selectedNode() string {
	fr := v.frame()
	if fr.cursor < 0 || fr.cursor >= len(v.rows) {
		return ""
	}
	return v.rows[fr.cursor].node
}

// render draws the current view to the tty.
func (v *treeView) render(w *os.File, width, height int) {
	v.height = height
	var out strings.Builder
	out.WriteString("\x1b[H\x1b[2J")
	if v.help {
		out.WriteString(helpText())
		w.WriteString(out.String())
		return
	}
	fr := v.frame()
	if fr.cursor < fr.top {
		fr.top = fr.cursor
	}
	if height > 0 && fr.cursor >= fr.top+height {
		fr.top = fr.cursor - height + 1
	}
	selected := v.selectedNode()
	selectedChildren := map[string]bool{}
	selectedEdges := map[string]bool{}
	if selected != "" {
		if n := v.g.Node(selected); n != nil {
			for _, c := range v.g.Children(n) {
				selectedChildren[c.Info.Abs] = true
				selectedEdges[selected+"\x00"+c.Info.Abs] = true
			}
		}
	}
	_ = selectedEdges
	lines := []string{}
	end := fr.top + height
	if end > len(v.rows) {
		end = len(v.rows)
	}
	for ri := fr.top; ri < end; ri++ {
		row := v.rows[ri]
		var line strings.Builder
		curColor := 0
		for _, c := range row.cells {
			color := 0
			if selected != "" {
				if c.text && c.owner == selected {
					color = 32
				} else if c.text && selectedChildren[c.owner] {
					color = 36
				} else if !c.text {
					// Edge cells belonging to the selected node's
					// outgoing edges are green.
					for id := range c.edges {
						_ = id
					}
					if edgeCellFrom(v.g, c, selected) {
						color = 32
					}
				}
			}
			if color != curColor {
				if color == 0 {
					line.WriteString("\x1b[39m")
				} else {
					line.WriteString(fmt.Sprintf("\x1b[%dm", color))
				}
				curColor = color
			}
			line.WriteRune(c.ch)
		}
		if curColor != 0 {
			line.WriteString("\x1b[39m")
		}
		lines = append(lines, line.String())
	}
	out.WriteString(strings.Join(lines, "\r\n"))
	w.WriteString(out.String())
}

// edgeCellFrom reports whether a line cell's edge originates at selected.
// Our cells don't retain edge origins, so this is approximated by the
// caller through node geometry: cells on rows below the selected node
// whose line reaches a child. For simplicity, it returns false and only
// node text is highlighted in that case; refined below in render2.
func edgeCellFrom(g *graph.Graph, c *cell, selected string) bool {
	return false
}

func helpText() string {
	return `
 ____         _ __       _
|  _ \   ___ |  _ \    _| |_  _ __  ___   ___
| | | | / _ \| |_) |  |_   _||  __|/ _ \ / _ \
| |_| ||  __/| .__/     | |  | |  |  __/|  __/
|____/  \__| |_|        | \__|_|   \___| \___|

Welcome to dep-tree's help section.

j      -> move one step down
k      -> move one step up
Ctrl d -> move half page down
Ctrl u -> move half page up
Enter  -> select the current node as the root node
q      -> navigate backwards on selected nodes or quit
h      -> show this help section
`
}

// handleKey processes one key press. It reports whether to quit and
// whether to redraw.
func (v *treeView) handleKey(key []byte) (bool, bool) {
	if v.help {
		v.help = false
		return false, true
	}
	if len(key) == 0 {
		return false, false
	}
	fr := v.frame()
	switch {
	case key[0] == 'q':
		if len(v.frames) > 1 {
			v.frames = v.frames[:len(v.frames)-1]
			v.relayout()
			return false, true
		}
		return true, false
	case key[0] == 'h':
		v.help = true
		return false, true
	case key[0] == 'j':
		if fr.cursor < len(v.rows)-1 {
			fr.cursor++
		}
		return false, true
	case key[0] == 'k':
		if fr.cursor > 0 {
			fr.cursor--
		}
		return false, true
	case key[0] == 4: // Ctrl+d
		step := v.height / 2
		if step <= 0 {
			step = 1
		}
		fr.cursor += step
		if fr.cursor >= len(v.rows) {
			fr.cursor = len(v.rows) - 1
		}
		return false, true
	case key[0] == 21: // Ctrl+u
		step := v.height / 2
		if step <= 0 {
			step = 1
		}
		fr.cursor -= step
		if fr.cursor < 0 {
			fr.cursor = 0
		}
		return false, true
	case key[0] == '\r' || key[0] == '\n':
		if node := v.selectedNode(); node != "" {
			v.frames = append(v.frames, treeFrame{root: node})
			v.relayout()
			return false, true
		}
		return false, false
	case len(key) >= 3 && key[0] == 0x1b && key[1] == '[' && key[2] == 'B':
		if fr.cursor < len(v.rows)-1 {
			fr.cursor++
		}
		return false, true
	case len(key) >= 3 && key[0] == 0x1b && key[1] == '[' && key[2] == 'A':
		if fr.cursor > 0 {
			fr.cursor--
		}
		return false, true
	}
	return false, false
}
