			prev := order[i-1]
			isChildOfPrev := false
			for _, p := range parents[n.Info.Abs] {
				if p == prev {
					isChildOfPrev = true
				}
			}
			if isChildOfPrev {
				ys[n.Info.Abs] = ys[prev.Info.Abs] + 2
			} else {
