		if len(ps) < 2 {
			continue
		}
		// Primary parent: deepest, earliest in layout order on ties.
		primary := ps[0]
		for _, parent := range ps[1:] {
			if depths[parent.Info.Abs] > depths[primary.Info.Abs] {
				primary = parent
			}
		}
		minParent := ps[0]
		for _, parent := range ps[1:] {
			if xs[parent.Info.Abs] < xs[minParent.Info.Abs] {
				minParent = parent
			}
		}
		if minParent == primary {
			continue
		}
		for _, parent := range ps {
			if xs[parent.Info.Abs] <= xs[minParent.Info.Abs] {
				continue
			}
			if c := get(xs[parent.Info.Abs], ys[child.Info.Abs]); c != nil {
				c.mask &^= dirN
			}
		}
	}
	// Place node texts.
