s=s.replace('''	// Draw edges.
	edgeID := 0''','''	// Draw edges.
	edgeID := 0
	type railSpan struct {
		col  int
		y1   int
		y2   int
		from string
	}
	var rails []railSpan''')
start=s.index('''			if isBack && child != n {''')
end=s.index('''			tri := cx - 1''')
old=s[start:end]
new='''			if isBack && child != n {
				rightCol := xs[n.Info.Abs] + len([]rune(n.Info.Display))
				targetEnd := xs[child.Info.Abs] + len([]rune(child.Info.Display))
				if rightCol <= targetEnd {
					rightCol = targetEnd + 1
				}
				// Offset when another source's rail overlaps.
				for {
					conflict := false
					for _, r := range rails {
						if r.col == rightCol && r.from != n.Info.Abs && py >= r.y1 && cy <= r.y2 {
							conflict = true
						}
					}
					if !conflict {
						break
					}
					rightCol += 2
				}
				rails = append(rails, railSpan{col: rightCol, y1: cy, y2: py, from: n.Info.Abs})
				// Target marker and horizontal segment.
				tx := targetEnd
				marker := get(tx, cy)
				marker.ch = '◁'
				marker.tri = true
				marker.edges[id] = true
				if marker.froms == nil { marker.froms = map[string]bool{} }
				marker.froms[n.Info.Abs] = true
				for x := tx + 1; x < rightCol; x++ {
					addLine(x, cy, dirW|dirE, id, n.Info.Abs)
				}
				if rightCol > tx {
					addLine(rightCol, cy, dirS|dirW, id, n.Info.Abs)
				}
				for y := cy + 1; y < py; y++ {
					addLine(rightCol, y, dirN|dirS, id, n.Info.Abs)
				}
				srcEnd := xs[n.Info.Abs] + len([]rune(n.Info.Display))
				for x := srcEnd; x < rightCol; x++ {
					addLine(x, py, dirW|dirE, id, n.Info.Abs)
				}
				src := get(rightCol, py)
				src.line = true
				src.mask |= dirN | dirW
				src.edges[id] = true
				if src.froms == nil { src.froms = map[string]bool{} }
				src.froms[n.Info.Abs] = true
				continue
			}
'''
s=s[:start]+new+s[end:]
open(p,'w').write(s)
