{"command":"cat > internal/js/hujson.go <<'EOF'
package js

import (
	"fmt"
	"strings"
)

// hujsonError validates JSON-with-comments syntax and returns an error
// string in the style of the hujson parser, or "" when valid.
func hujsonError(data []byte) string {
	p := &hujsonParser{s: string(data)}
	p.skip()
	if err := p.value(); err != "" {
		return err
	}
	p.skip()
	if p.pos < len(p.s) {
		return p.errAt(p.pos, fmt.Sprintf("invalid character %q after top-level value", rune(p.s[p.pos])))
	}
	return ""
}

type hujsonParser struct {
	s   string
	pos int
}

func (p *hujsonParser) lineCol(pos int) (int, int) {
	line := 1
	col := 1
	for i := 0; i < pos && i < len(p.s); i++ {
		if p.s[i] == '\n' {
			line++
			col = 1
		} else {
			col++
		}
	}
	return line, col
}

func (p *hujsonParser) errAt(pos int, msg string) string {
	line, col := p.lineCol(pos)
	return fmt.Sprintf("hujson: line %d, column %d: %s", line, col, msg)
}

func (p *hujsonParser) skip() {
	for p.pos < len(p.s) {
		c := p.s[p.pos]
		if c == ' ' || c == '\t' || c == '\n' || c == '\r' {
			p.pos++
			continue
		}
		if c == '/' && p.pos+1 < len(p.s) && p.s[p.pos+1] == '/' {
			for p.pos < len(p.s) && p.s[p.pos] != '\n' {
				p.pos++
