			if p.pos >= len(p.s) {
				return p.errAt(p.pos, "parsing value: unexpected EOF")
			}
			return p.errAt(p.pos, fmt.Sprintf("invalid character '%c' after object key", p.s[p.pos]))
		}
		p.pos++
		if err := p.value(); err != "" {
			return err
		}
		p.skip()
		if p.pos >= len(p.s) {
			return p.errAt(p.pos, "parsing value: unexpected EOF")
		}
		if p.s[p.pos] == '}' {
			p.pos++
			return ""
		}
		if p.s[p.pos] != ',' {
			return p.errAt(p.pos, fmt.Sprintf("invalid character '%c' after object value", p.s[p.pos]))
		}
		p.pos++
		p.skip()
		if p.pos < len(p.s) && p.s[p.pos] == '}' {
			p.pos++
			return ""
		}
	}
}

func (p *hujsonParser) array() string {
	p.pos++ // [
	p.skip()
	if p.pos >= len(p.s) {
		return p.errAt(p.pos, "parsing value: unexpected EOF")
	}
	if p.s[p.pos] == ']' {
		p.pos++
		return ""
	}
	for {
		if err := p.value(); err != "" {
			return err
		}
		p.skip()
		if p.pos >= len(p.s) {
			return p.errAt(p.pos, "parsing value: unexpected EOF")
		}
		if p.s[p.pos] == ']' {
			p.pos++
			return ""
		}
		if p.s[p.pos] != ',' {
			return p.errAt(p.pos, fmt.Sprintf("invalid character '%c' after array element", p.s[p.pos]))
		}
		p.pos++
		p.skip()
		if p.pos < len(p.s) && p.s[p.pos] == ']' {
			p.pos++
			return ""
		}
	}
}

func (p *hujsonParser) str() string {
	// p.s[p.pos] is the opening quote.
	p.pos++
	for p.pos < len(p.s) {
		c := p.s[p.pos]
		if c == '\\' {
			p.pos += 2
			continue
		}
		if c == '"' {
			p.pos++
			return ""
		}
		p.pos++
	}
	return p.errAt(p.pos-1, "parsing string: unexpected EOF")
}

func isLetterByte(c byte) bool {
	return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')
}

func isAlnumByte(c byte) bool {
	return isLetterByte(c) || (c >= '0' && c <= '9') || c == '_' || c == '-'
}

func validNumber(tok string) bool {
	// Strict JSON number grammar.
	i := 0
	if i < len(tok) && tok[i] == '-' {
		i++
	}
	if i >= len(tok) {
		return false
	}
	if tok[i] == '0' {
		i++
	} else if tok[i] >= '1' && tok[i] <= '9' {
		for i < len(tok) && tok[i] >= '0' && tok[i] <= '9' {
			i++
		}
	} else {
		return false
	}
	if i < len(tok) && tok[i] == '.' {
		i++
		if i >= len(tok) {
			return false
		}
		for i < len(tok) && tok[i] >= '0' && tok[i] <= '9' {
			i++
		}
	}
	if i < len(tok) && (tok[i] == 'e' || tok[i] == 'E') {
		i++
		if i < len(tok) && (tok[i] == '+' || tok[i] == '-') {
			i++
		}
		if i >= len(tok) {
			return false
		}
		for i < len(tok) && tok[i] >= '0' && tok[i] <= '9' {
			i++
		}
	}
	return i == len(tok) && !strings.Contains(tok, "_")
}
