{"command":"cd /workspace && python3 - << 'PY'
p="internal/graph/graph.go"; s=open(p).read()
start=s.index('// Tree builds the nested tree representation')
end=s.index('// CircularDependencies returns cycles')
new='''// Tree builds the nested tree representation used by the tree command
// and collects the circular dependencies encountered along the way.
//
// The graph is first walked depth-first from the entrypoint, building
// a spanning tree. The nested representation then follows every graph
// edge except those that point back to an ancestor in the spanning
// tree; such back edges are reported as circular dependencies.
func (g *Graph) Tree(entryAbs string) (map[string]interface{}, [][]string) {
	entry := g.Node(entryAbs)
	if entry == nil {
		return nil, [][]string{}
	}
	parent := map[*Node]*Node{entry: nil}
	visited := map[*Node]bool{}
	inStack := map[*Node]bool{}
	var stack []*Node
	cycles := [][]string{}
	seenCycle := map[string]bool{}
	var dfs func(n *Node)
	dfs = func(n *Node) {
		visited[n] = true
		inStack[n] = true
		stack = append(stack, n)
		for _, child := range g.Children(n) {
			if !visited[child] {
				parent[child] = n
				dfs(child)
			} else if inStack[child] {
				idx := 0
				for i, s := range stack {
					if s == child {
						idx = i
						break
					}
				}
				cycle := []string{}
				for _, s := range stack[idx:] {
					cycle = append(cycle, s.Info.Display)
				}
				cycle = append(cycle, child.Info.Display)
				key := strings.Join(cycle, "\\x00")
				if !seenCycle[key] {
					seenCycle[key] = true
					cycles = append(cycles, cycle)
				}
			}
		}
		stack = stack[:len(stack)-1]
		inStack[n] = false
	}
	dfs(entry)
	isAncestor := func(candidate, n *Node) bool {
		for cur := n; cur != nil; cur = parent[cur] {
			if cur == candidate {
				return true
			}
		}
		return false
	}
	var serialize func(n *Node) map[string]interface{}
	serialize = func(n *Node) map[string]interface{} {
		var out map[string]interface{}
		for _, child := range g.Children(n) {
			if isAncestor(child, n) {
				continue
			}
			if out == nil {
				out = map[string]interface{}{}
			}
			out[child.Info.Display] = serialize(child)
		}
		return out
	}
	root := map[string]interface{}{entry.Info.Display: serialize(entry)}
	return root, cycles
}

'''
s=s[:start]+new+s[end:]
open(p,'w').write(s)
