// Each cycle is reported starting at the lowest-ranked node it
// contains, where nodes are ranked by the FNV-1a hash of their
// absolute path.
func (g *Graph) CircularDependencies() [][]string {
	nodes := append([]*Node{}, g.Nodes...)
	sort.Slice(nodes, func(i, j int) bool {
		idi, idj := langcore.ID(nodes[i].Info.Abs), langcore.ID(nodes[j].Info.Abs)
		if idi != idj {
			return idi < idj
		}
		return nodes[i].Info.Abs < nodes[j].Info.Abs
	})
	rank := map[*Node]int{}
	for i, n := range nodes {
		rank[n] = i
	}
	cycles := [][]string{}
	for _, start := range nodes {
		var path []*Node
		onPath := map[*Node]bool{}
		var dfs func(n *Node)
		dfs = func(n *Node) {
			for _, child := range g.Children(n) {
				if child == start {
					if len(path) >= 2 {
						cycle := []string{}
						for _, p := range path {
							cycle = append(cycle, p.Info.Display)
						}
						cycle = append(cycle, start.Info.Display)
						cycles = append(cycles, cycle)
					}
					continue
				}
				if rank[child] < rank[start] || onPath[child] {
					continue
				}
				onPath[child] = true
				path = append(path, child)
				dfs(child)
				path = path[:len(path)-1]
				delete(onPath, child)
			}
		}
		path = []*Node{start}
		onPath[start] = true
		dfs(start)
	}
	return cycles
}

