s=s.replace('''	view := newTreeView(g, entry)
	// Enter the alternate screen.
	tty.WriteString("\\x1b[?1049h\\x1b[?25l")
	defer tty.WriteString("\\x1b[?25h\\x1b[?1049l")
	width, height := ttySize(tty)
	view.render(tty, width, height)
	buf := make([]byte, 64)
	for {
		n, err := tty.Read(buf)
		if err != nil {
			return err
		}
		if n == 0 {
			continue
		}
		quit, redraw := view.handleKey(buf[:n])
		if quit {
			return nil
		}
		if redraw {
			width, height = ttySize(tty)
			view.render(tty, width, height)
		}
	}
}''','''	view := newTreeView(g, entry)
	// Enter the alternate screen.
	tty.WriteString("\\x1b[?1049h\\x1b[?25l")
	defer tty.WriteString("\\x1b[?25h\\x1b[?1049l")
	winch := make(chan os.Signal, 1)
	signal.Notify(winch, syscall.SIGWINCH)
	defer signal.Stop(winch)
	type readResult struct {
		data []byte
		err  error
	}
	reads := make(chan readResult, 1)
	go func() {
		buf := make([]byte, 64)
		for {
			n, err := tty.Read(buf)
			data := append([]byte{}, buf[:n]...)
			reads <- readResult{data, err}
			if err != nil {
				return
			}
		}
	}()
	width, height := ttySize(tty)
	view.render(tty, width, height)
	for {
		select {
		case <-winch:
			width, height = ttySize(tty)
			view.render(tty, width, height)
		case result := <-reads:
			if result.err != nil {
				return result.err
			}
			// Process the input one key at a time so that batched
			// keys (e.g. from a paste) all take effect.
			data := result.data
			quit := false
			redraw := false
